  ui_story_5072_50720202_1_dialog_content = "Veja, o bico não é apenas um ótimo massageador, ele também pode quebrar cascas de nozes.",
  ui_story_5072_50720202_2_dialog_content = "Que maravilha!",
  ui_story_5072_50720202_3_dialog_content = "Eu preciso ter isso! Apenas diga o seu preço, qualquer preço...",
  ui_story_5072_50720202_4_dialog_content = "Para ser honesto, eu sonho com um quebra-nozes assim há muito tempo, então...",
  ui_story_5072_50720202_5_dialog_content = "Aham…",
  ui_story_5072_50720202_6_dialog_content = "Ops, esqueci completamente da minha senhora! Ela deve estar cansada de me esperar.",
  ui_story_5072_50720202_7_dialog_content = "Conversaremos mais tarde se você estiver interessado.",
  ui_story_5072_50720202_8_dialog_content = "Está ficando tarde e minha senhora precisa voltar. Não posso mantê-la acordada.",
  ui_story_5072_50720202_9_dialog_content = "Espere aí, e o pássaro mecânico...?",
  ui_story_5072_50720202_10_dialog_content = "Não vendemos coisas boas para comerciantes sujos como ele. Vamos, estamos saindo!",
  ui_story_5072_50720202_11_dialog_content = "Claro, minha senhora. Eu estava apenas enrolando ele. Ele não conseguiria por nenhum preço!",
  ui_story_5072_50720202_12_dialog_content = "Você estava me enrolando?",
  ui_story_5072_50720202_13_dialog_content = "Não, isso é chamado de o que vai, volta!",
  ui_story_5072_50720202_14_dialog_content = "Adeus.",
  ui_story_5072_50720202_15_dialog_content = "Isso demorou um pouco mais do que eu pensava.",
  ui_story_5072_50720202_16_dialog_content = "Aconteceu algo inesperado?",
  ui_story_5072_50720202_17_dialog_content = "De fato.",
  ui_story_5072_50720202_18_dialog_content = "Encontrei antiguidades e falsificações escondidas no segundo andar.",
  ui_story_5072_50720202_19_dialog_content = "Mas eles estavam envoltos em uma aura preta peculiar... e eles até se moviam!",
  ui_story_5072_50720202_20_dialog_content = "Eles quase conseguiram me cercar.",
  ui_story_5072_50720202_21_dialog_content = "Era como uma armadilha apenas esperando por mim.",
  ui_story_5072_50720202_22_dialog_content = "Armadilha? Ele planejou isso? Não, ele não poderia ter.",
  ui_story_5072_50720202_23_dialog_content = "Então, ele não é o problema?",
  ui_story_5072_50720202_24_dialog_content = "Ele não parecia suspeito nem tentou esconder nenhum motivo para mim.",
  ui_story_5072_50720202_25_dialog_content = "Se ele fez isso intencionalmente, eu teria percebido.",
  ui_story_5072_50720202_26_dialog_content = "Mas é bastante bizarro. Objetos com uma aura ameaçadora e se movendo sozinhos...",
  ui_story_5072_50720202_27_dialog_content = "É como se eles estivessem encantados ou amaldiçoados e ativados pela sua presença...",
  ui_story_5072_50720202_28_dialog_content = "Amaldiçoado...?!",
  ui_story_5072_50720202_29_dialog_content = "Fique tranquilo. A maldição que eu falo se refere a como as pessoas de Longzhou imploram aos deuses para trazer desastre aos seus inimigos.",
  ui_story_5072_50720202_30_dialog_content = "Em Longzhou, acreditamos que tudo é senciente.",
  ui_story_5072_50720202_31_dialog_content = "Sejam Fiendlings nascidos da natureza ou relíquias antigas, todos eles possuem anima.",
  ui_story_5072_50720202_32_dialog_content = "Às vezes, eles são adorados e orados, o que difere muito dos costumes daqui.",
  ui_story_5072_50720202_33_dialog_content = "Vou anotar isso, caso tenha algo a ver com a sua maldição.",
  ui_story_5072_50720202_34_dialog_content = "Sabemos o que está acontecendo assim que descobrirmos o mentor por trás dessas cercas.",
  ui_story_5072_50720202_35_dialog_content = "Entendo, a missão tem precedência.",
  ui_story_5072_50720202_36_dialog_content = "Ah, uma coisinha...",
  ui_story_5072_50720202_37_dialog_content = "O que foi?",
  ui_story_5072_50720202_38_dialog_content = "Ah, nada.",
  ui_story_5072_50720202_39_dialog_content = "(A senhorita Armilla estava ocupada conversando com o homem e não poderia ter me avisado.)",
  ui_story_5072_50720202_40_dialog_content = "(Então de onde veio o aviso?)",
  ui_story_5072_50720202_41_dialog_content = "(Ou talvez eu estivesse ouvindo coisas...)",
  ui_story_5072_50720301_1_dialog_content = "Desculpe, ainda não estou acostumada a me arrumar.",
  ui_story_5072_50720301_2_dialog_content = "Tudo bem. Os acessórios e o penteado realmente levam tempo.",
  ui_story_5072_50720301_3_dialog_content = "Mas você vai pegar o jeito se praticar o suficiente durante alguns dias.",
  ui_story_5072_50720301_4_dialog_content = "Me preocupo um pouco...",
  ui_story_5072_50720301_5_dialog_content = "A reunião não foi bem. O lojista vai nos ver hoje?",
  ui_story_5072_50720301_6_dialog_content = "Relaxe, é assim que as conversas de negócios geralmente são. Eu já vi pior.",
  ui_story_5072_50720301_7_dialog_content = "Estamos apenas tentando descobrir se ele poderia esclarecer algo sobre o seu encontro de ontem à noite.",
  ui_story_5072_50720301_8_dialog_content = "O ponto é os patrocinadores por trás dele, então não fique tão tensa!",
  ui_story_5072_50720301_9_dialog_content = "Entendido.",
  ui_story_5072_50720301_10_dialog_content = "Certo, vamos então, minha senhora.",
  ui_story_5072_50720301_11_dialog_content = "Nos encontramos novamente, senhor.",
  ui_story_5072_50720301_12_dialog_content = "Bem, se não é o pequeno encrenqueiro de ontem...",
  ui_story_5072_50720301_13_dialog_content = "C-Como você ousa falar comigo assim?",
  ui_story_5072_50720301_14_dialog_content = "Eu acabei de fazer. O que você vai fazer a respeito?",
  ui_story_5072_50720301_15_dialog_content = "Estava tudo bem ontem à noite até vocês dois aparecerem e meu depósito de alguma forma se tornar uma bagunça!",
  ui_story_5072_50720301_16_dialog_content = "Os guardas também desmaiaram e não conseguiram se lembrar do que aconteceu!",
  ui_story_5072_50720301_17_dialog_content = "Parecia que eles foram drogados pelo... algo de Longzhou...",
  ui_story_5072_50720301_18_dialog_content = "Ei, não me diga que você está por trás de tudo isso?!",
  ui_story_5072_50720301_19_dialog_content = "Que rude da sua parte suspeitar de mim!",
  ui_story_5072_50720301_20_dialog_content = "Estava pensando em trocar um favor dos Lins pelos oficiais em Umbraton para uma investigação completa para você.",
  ui_story_5072_50720301_21_dialog_content = "Acho que isso não é necessário agora!",
  ui_story_5072_50720301_22_dialog_content = "E-Espere, por favor me ajude se você tiver influência!",
  ui_story_5072_50720301_23_dialog_content = "Sou um pequeno operador aqui. Não posso me dar ao luxo de perder nada.",
  ui_story_5072_50720301_24_dialog_content = "Bem, falsificações são tudo o que você tem, e eu não tenho tempo para isso!",
  ui_story_5072_50720301_25_dialog_content = "Se você não quer trabalhar comigo, outra pessoa vai querer.",
  ui_story_5072_50720301_26_dialog_content = "Estou indo embora. Adeus!",
  ui_story_5072_50720301_27_dialog_content = "Ufa, acabou.",
  ui_story_5072_50720301_28_dialog_content = "Meu desempenho recebeu uma nota de aprovação?",
  ui_story_5072_50720301_29_dialog_content = "Passando? Foi perfeito!",
  ui_story_5072_50720301_30_dialog_content = "Até eu fui intimidado por isso, minha senhora.",
  ui_story_5072_50720301_31_dialog_content = "Bem, eu realmente senti a confiança aumentar quanto mais eu me envolvia com o papel.",
  ui_story_5072_50720301_32_dialog_content = "Antes que você percebesse, eu estava dizendo coisas que normalmente não diria.",
  ui_story_5072_50720301_33_dialog_content = "<size=30>Felizmente, estou em Twin Pavilions Bay...</size>",
  ui_story_5072_50720301_34_dialog_content = "<size=30>(Se os caras de Umbraton ouvissem isso... Eu teria que cavar um buraco e me esconder em um casulo de espinhos.)</size>",
  ui_story_5072_50720301_35_dialog_content = "Por que não aproveitamos isso e continuamos nossos esforços?",
  ui_story_5072_50720301_36_dialog_content = "Há muitas lojas na minha lista.",
  ui_story_5072_50720301_37_dialog_content = "Faremos perguntas e anotaremos as respostas.",
  ui_story_5072_50720301_38_dialog_content = "Então você pode se esgueirar para dentro à noite e confirmar se eles estão dizendo a verdade ou não.",
  ui_story_5072_50720301_39_dialog_content = "Sim, isso se encaixa melhor para mim.",
  ui_story_5072_50720301_40_dialog_content = "Vamos lá, você está pegando o jeito de ser um socialite.",
  ui_story_5072_50720301_41_dialog_content = "É preciso esforço para conversar com os lojistas.",
  ui_story_5072_50720301_42_dialog_content = "Você deve fazer compras e apreciar as vistas nessa forma quando tiver tempo.",
  ui_story_5072_50720301_43_dialog_content = "O que? Uh, está tudo bem.",
  ui_story_5072_50720301_44_dialog_content = "O que eu disse sobre estar muito tenso? Você sequer comeu a fruta que comprou ontem?",
  ui_story_5072_50720301_45_dialog_content = "Eu não queria que estragassem, então comi algumas laranjas.",
  ui_story_5072_50720301_46_dialog_content = "Para compensar, vou te oferecer uma especialidade de Longzhou quando terminarmos tudo isso.",
  ui_story_5072_50720301_47_dialog_content = "Hã, bom...",
  ui_story_5072_50720301_48_dialog_content = "Essa é uma ordem do seu chefe.",
  ui_story_5072_50720301_49_dialog_content = "Ok, isso parece bom para mim então.",
  ui_story_5072_50720401_1_dialog_content = "Tudo bem, uma invasão bem sucedida esta noite.",
  ui_story_5072_50720401_2_dialog_content = "A Srta. Armilla é certamente minuciosa em suas investigações...",
  ui_story_5072_50720401_3_dialog_content = "Duas cestas de bolinhos de sopa, dois leites de soja e dois palitos de massa frita para viagem.",
  ui_story_5072_50720401_4_dialog_content = "Ei, vejo que é um especialista em especialidades de Longzhou.",
  ui_story_5072_50720401_5_dialog_content = "Não exatamente. Você é apoiado pela famosa Guilda da Concha Vermelha e isso faz de você uma franquia conhecida.",
  ui_story_5072_50720401_6_dialog_content = "Obrigado pelo reconhecimento. Deixe-me pegar o seu pedido para você.",
  ui_story_5072_50720401_7_dialog_content = "Antes de você fazer isso, estou curioso se você ouviu algo interessante pela área oeste?",
  ui_story_5072_50720401_8_dialog_content = "Minha senhora está um pouco entediada e gostaria de ouvir algumas histórias!",
  ui_story_5072_50720401_9_dialog_content = "Histórias? Bem, sim, os ricos de lá têm falado sobre isso o tempo todo recentemente.",
  ui_story_5072_50720401_10_dialog_content = "Um colecionador com origem em Lumópolis andou comprando antiguidades de Longzhou.",
  ui_story_5072_50720401_11_dialog_content = "Supostamente porque as relíquias continham espíritos estrangeiros!",
  ui_story_5072_50720401_12_dialog_content = "Pffff—",
  ui_story_5072_50720401_13_dialog_content = "Ele achou que conseguiria uma princesa estrangeira juntando todos os fragmentos?",
  ui_story_5072_50720401_14_dialog_content = "Louco, não é? E ele enlouqueceu apenas alguns dias atrás!",
  ui_story_5072_50720401_15_dialog_content = "Louco, você disse? Como exatamente?",
  ui_story_5072_50720401_16_dialog_content = "Ele acontece de ser um amigo do meu chefe e mora em uma grande mansão.",
  ui_story_5072_50720401_17_dialog_content = "Não consigo nem dar uma olhada nele quando deixo comida nas entregas.",
  ui_story_5072_50720401_18_dialog_content = "Confira se estiver interessado. Posso te dar o endereço. Todo mundo sabe onde fica.",
  ui_story_5072_50720401_19_dialog_content = "Fantástico, aqui está uma gorjeta para você.",
  ui_story_5072_50720401_20_dialog_content = "Tudo bem! Muito obrigado a ambos.",
  ui_story_5072_50720401_21_dialog_content = "Então, o que é a Guilda Red Shell?",
  ui_story_5072_50720401_22_dialog_content = "Uma das nozes mais difíceis de quebrar que visitamos antes.",
  ui_story_5072_50720401_23_dialog_content = "Os garçons do lugar certamente conversam com muitas pessoas.",
  ui_story_5072_50720401_24_dialog_content = "Sempre posso obter deles as informações que não consigo obter por conta própria.",
  ui_story_5072_50720401_25_dialog_content = "Quando terminarmos de comer, vamos visitar o colecionador de Lumópolis. Talvez tenhamos uma descoberta.",
  ui_story_5072_50720401_26_dialog_content = "Claro... Os bolinhos de sopa são deliciosos...",
  ui_story_5072_50720401_27_dialog_content = "Você já começou a cavar? Quando eles serviram?",
  ui_story_5072_50720401_28_dialog_content = "No entanto, a visita durante o dia foi um fracasso. Eu não consegui vê-lo nem com minha identidade falsa...",
  ui_story_5072_50720401_29_dialog_content = "O homem é excêntrico, de fato.",
  ui_story_5072_50720401_30_dialog_content = "A mansão está perto de uma rua movimentada, mas emana uma vibe ameaçadora e arrepiante...",
  ui_story_5072_50720401_31_dialog_content = "Não...",
  ui_story_5072_50720401_32_dialog_content = "Ouvi uma coisa...",
  ui_story_5072_50720401_33_dialog_content = "Não chegue mais perto, malvado...",
  ui_story_5072_50720401_34_dialog_content = "Esse é o coletor!",
  ui_story_5072_50720401_35_dialog_content = "Ele não está em seu juízo perfeito... O que ele está tentando dizer?",
  ui_story_5072_50720401_36_dialog_content = "Espírito maligno! É o espírito maligno!",
  ui_story_5072_50720401_37_dialog_content = "Um espírito maligno está vagando pela Twin Pavilions Bay, perambulando...",
  ui_story_5072_50720401_38_dialog_content = "Se você não tomar cuidado, vai perder a cabeça!",
  ui_story_5072_50720401_39_dialog_content = "Ahhh!",
  ui_story_5072_50720401_40_dialog_content = "O que está acontecendo?",
  ui_story_5072_50720401_41_dialog_content = "...",
  ui_story_5072_50720401_42_dialog_content = "Todos os guardas foram nocauteados!",
  ui_story_5072_50720401_43_dialog_content = "...",
  ui_story_5072_50720401_44_dialog_content = "E o coletor também...",
  ui_story_5072_50720401_45_dialog_content = "Você...",
  ui_story_5072_50720401_46_dialog_content = "Quem é você?!",
  ui_story_5072_50720401_47_dialog_content = "Você está segurando uma arma! Você é o assassino?!",
  ui_story_5072_50720401_48_dialog_content = "...",
  ui_story_5072_50720401_49_dialog_content = "A aura negra é a mesma das antiguidades amaldiçoadas!",
  ui_story_5072_50720401_50_dialog_content = "É este o espírito maligno do qual o colecionador falou?",
  ui_story_5072_50720401_51_dialog_content = "(!!!)",
  ui_story_5072_50720401_52_dialog_content = "Tão rápido!",
  ui_story_5072_50720401_53_dialog_content = "Há tantas sombras no quarto...",
  ui_story_5072_50720401_54_dialog_content = "Não, não eram apenas sombras comuns... Elas pareciam hostis, muito parecidas com...",
  ui_story_5072_50720401_55_dialog_content = "Energia da espada?!",
  ui_story_5072_50720401_56_dialog_content = "<color=#e8d9bb>Clang—Ka-thunk—</color>",
  ui_story_5072_50720401_57_dialog_content = "Ele está tentando destruir tudo aqui?! De jeito nenhum!",
  ui_story_5072_50720401_58_dialog_content = "Ha—",
  ui_story_5072_50720401_59_dialog_content = "Eu vou lutar com você!",
  ui_story_5072_50720402_1_dialog_content = "<color=#e8d9bb>Uau—!</color>",
  ui_story_5072_50720402_2_dialog_content = "...",
  ui_story_5072_50720402_3_dialog_content = "Silvo...",
  ui_story_5072_50720402_4_dialog_content = "Eu não entendo... Eu deveria ser capaz de derrubá-lo com minha espada mágica.",
  ui_story_5072_50720402_5_dialog_content = "Mas essas sombras continuam vindo e se reformando após cada corte, como se eu não as tivesse atingido...",
  ui_story_5072_50720402_6_dialog_content = "E eles estão se aproximando cada vez mais...",
  ui_story_5072_50720402_7_dialog_content = "De alguma forma, tenho que mantê-los à distância.",
  ui_story_5072_50720402_8_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5072_50720402_9_dialog_content = "Ai...",
  ui_story_5072_50720402_10_dialog_content = "Este quarto está cheio de coisas. Não há mais espaço para correr.",
  ui_story_5072_50720402_11_dialog_content = "Essa não...",
  ui_story_5072_50720402_12_dialog_content = "Roaaaar—",
  ui_story_5072_50720402_13_dialog_content = "A energia da espada dele está me restringindo!",
  ui_story_5072_50720402_14_dialog_content = "Dói com todas as emoções e pensamentos negativos...",
  ui_story_5072_50720402_15_dialog_content = "Controle-se.",
  ui_story_5072_50720402_16_dialog_content = "É a mesma voz que me avisou antes?",
  ui_story_5072_50720402_17_dialog_content = "Então eu não estava ouvindo coisas, mas na verdade...",
  ui_story_5072_50720402_18_dialog_content = "Minha espada?!",
  ui_story_5072_50720402_19_dialog_content = "Mantenha o foco. A visibilidade aqui é muito ruim para você ver a verdade ocultada pelas sombras.",
  ui_story_5072_50720402_20_dialog_content = "Não se preocupe com a aura negra. Ela está apenas ali para te distrair!",
  ui_story_5072_50720402_21_dialog_content = "Seu alvo está bem no final.",
  ui_story_5072_50720402_22_dialog_content = "Salte e ataque. Eu vou traçar o caminho para você.",
  ui_story_5072_50720402_23_dialog_content = "Não tenho tempo para ponderar tudo o que você disse, mas...",
  ui_story_5072_50720402_24_dialog_content = "Entendi e vou confiar em você!",
  ui_story_5072_50720402_25_dialog_content = "(!!!)",
  ui_story_5072_50720402_26_dialog_content = "Eu fiz isso! E um sólido também.",
  ui_story_5072_50720402_27_dialog_content = "...",
  ui_story_5072_50720402_28_dialog_content = "As sombras se dissiparam. Agora, deixe-me ver quem você realmente é.",
  ui_story_5072_50720402_29_dialog_content = "...",
  ui_story_5072_50720402_30_dialog_content = "O quê? Não foi o servente que nos contou a história?",
  ui_story_5072_50720402_31_dialog_content = "Ele é apenas um cara comum, então como ele poderia ser tão duro...?",
  ui_story_5072_50720402_32_dialog_content = "Talvez seja a espada dele... Provavelmente tem poderes especiais como os meus.",
  ui_story_5072_50720402_33_dialog_content = "...",
  ui_story_5072_50720402_34_dialog_content = "Congele.",
  ui_story_5072_50720402_35_dialog_content = "Aqui!",
  ui_story_5072_50720402_36_dialog_content = "Alguém está entrando...?",
  ui_story_5072_50720402_37_dialog_content = "Acabei de ver uma figura estranha com uma espada enorme entrar!",
  ui_story_5072_50720402_38_dialog_content = "Mas é onde o colecionador louco vive. Devemos deixá-lo em paz.",
  ui_story_5072_50720402_39_dialog_content = "Não, se conseguirmos resolver o caso, provavelmente seremos recompensados tanto pelo Senhor da Cidade quanto pela guilda!",
  ui_story_5072_50720402_40_dialog_content = "Isso não é bom. Alguém está entrando agora mesmo...",
  ui_story_5072_50720402_41_dialog_content = "Será ruim se eles me virem.",
  ui_story_5072_50720402_42_dialog_content = "Devo ir e reportar à Senhorita Armilla.",
  ui_story_5072_50720501_1_dialog_content = "Senhor, espero que você possa oferecer uma explicação adequada para a Guilda Red Shell.",
  ui_story_5072_50720501_2_dialog_content = "Nos negócios, a integridade é primordial, sem exceções.",
  ui_story_5072_50720501_3_dialog_content = "Mas se é o que aconteceu ontem à noite ou minhas consultas anteriores relacionadas a antiguidades...",
  ui_story_5072_50720501_4_dialog_content = "Você não falou uma única palavra de verdade, então o que é isso tudo?",
  ui_story_5072_50720501_5_dialog_content = "A Guilda Red Shell mentiu?",
  ui_story_5072_50720501_6_dialog_content = "Com certeza fizeram. Eles afirmaram que o colecionador desequilibrado não tinha nada a ver com eles, quando era tudo sobre eles!",
  ui_story_5072_50720501_7_dialog_content = "Tudo na casa da vítima foi comprado deles. Ouvi dizer que eles também enviaram o assassino.",
  ui_story_5072_50720501_8_dialog_content = "Não, isso não é verdade de jeito nenhum!",
  ui_story_5072_50720501_9_dialog_content = "O caso da noite passada foi abrupto e inesperado. Só precisamos de tempo para investigar!",
  ui_story_5072_50720501_10_dialog_content = "Tudo bem, quanto ao envolvimento do Red Shell no ataque...",
  ui_story_5072_50720501_11_dialog_content = "A Guilda Ziyun aguardará sua investigação.",
  ui_story_5072_50720501_12_dialog_content = "Mas gostaríamos que você explicasse as ordens do mercado negro.",
  ui_story_5072_50720501_13_dialog_content = "Quando eu visitei há alguns dias, você deixou claro que nunca se envolveria em tais transações.",
  ui_story_5072_50720501_14_dialog_content = "Mas agora que veio à tona, o que você tem a dizer sobre isso?",
  ui_story_5072_50720501_15_dialog_content = "Uau, sair da frigideira e entrar no fogo!",
  ui_story_5072_50720501_16_dialog_content = "Eu sabia que a Red Shell tem ligações com o mercado negro!",
  ui_story_5072_50720501_17_dialog_content = "Por favor, acalmem-se todos e relaxem. Tudo será resolvido a tempo.",
  ui_story_5072_50720501_18_dialog_content = "Nós lidamos com aquelas antiguidades de Longzhou de origens desconhecidas.",
  ui_story_5072_50720501_19_dialog_content = "Mas todos nós sabemos que para se dar bem em Umbraton e Twin Pavilions Bay, você precisa apertar a mão de ambos os lados.",
  ui_story_5072_50720501_20_dialog_content = "Não é que eu me recuse a divulgar, mas conexões clandestinas não são algo que você queira tornar público...",
  ui_story_5072_50720501_21_dialog_content = "Eu fiz isso por preocupação com a paz em Twin Pavilions Bay.",
  ui_story_5072_50720501_22_dialog_content = "Pela paz na Baía? Parece mais uma preocupação com o seu próprio negócio para mim.",
  ui_story_5072_50720501_23_dialog_content = "Mas nada disso é importante para onde estamos agora.",
  ui_story_5072_50720501_24_dialog_content = "Incluindo minha senhora aqui, muitas pessoas viram na noite passada que o assassino trabalha para você.",
  ui_story_5072_50720501_25_dialog_content = "Se o assassinato-roubo for descoberto, não haverá lugar para a sua guilda nesta cidade.",
  ui_story_5072_50720501_26_dialog_content = "Ei, não seja tão precipitado agora!",
  ui_story_5072_50720501_27_dialog_content = "Negócio de mercado negro ainda é negócio.",
  ui_story_5072_50720501_28_dialog_content = "Mas apenas bandidos saqueariam e pilhariam dessa maneira.",
  ui_story_5072_50720501_29_dialog_content = "De jeito nenhum eu arruinaria o futuro da minha guilda por um lucro tão pequeno!",
  ui_story_5072_50720501_30_dialog_content = "Você está falando a verdade?",
  ui_story_5072_50720501_31_dialog_content = "Juro pela minha própria vida!",
  ui_story_5072_50720501_32_dialog_content = "Não acho que você correria esse risco também. Na verdade, suspeito que esse cara esteja secretamente trabalhando para outra pessoa.",
  ui_story_5072_50720501_33_dialog_content = "Então você esteve me sondando para obter informações todo esse tempo?!",
  ui_story_5072_50720501_34_dialog_content = "Não se desvie do assunto. Voltaremos a como você mentiu para mim.",
  ui_story_5072_50720501_35_dialog_content = "No entanto, descobrir quem está pagando o cara será benéfico para nós dois.",
  ui_story_5072_50720501_36_dialog_content = "Ele é apenas um funcionário médio. Não vejo por que alguém gostaria de comprar sua lealdade.",
  ui_story_5072_50720501_37_dialog_content = "Então só resta uma possibilidade.",
  ui_story_5072_50720501_38_dialog_content = "O que foi?",
  ui_story_5072_50720501_39_dialog_content = "Algumas das relíquias que circulam no mercado negro são poderosos artefatos que poderiam controlar a mente de quem os segura.",
  ui_story_5072_50720501_40_dialog_content = "Afinal de contas, aquele cara lutou como um campeão com uma espada... Ah, e outra coisa.",
  ui_story_5072_50720501_41_dialog_content = "Ouvi dizer que o jovem mestre da sua guilda também testemunhou o assassino ontem à noite?",
  ui_story_5072_50720501_42_dialog_content = "Quais são as chances de ele estar por perto justamente quando um de seus funcionários estava cometendo um crime?",
  ui_story_5072_50720501_43_dialog_content = "É difícil não sentir algo suspeito nisso.",
  ui_story_5072_50720501_44_dialog_content = "Ei, pare de acusar pessoas sem provas!",
  ui_story_5072_50720501_45_dialog_content = "Ele foi a um bar com alguns amigos e simplesmente tropeçou nisso no caminho de volta.",
  ui_story_5072_50720501_46_dialog_content = "Se formos um passo além, isso não tornaria sua senhora uma suspeita também?",
  ui_story_5072_50720501_47_dialog_content = "Ah, essa é uma nova teoria. Por que você não me explica como?",
  ui_story_5072_50720501_48_dialog_content = "É normal para o nosso jovem mestre bastante extrovertido estar fora bebendo à noite.",
  ui_story_5072_50720501_49_dialog_content = "Mas o que sua senhora estava fazendo fora e por aí em vez de ficar em casa?",
  ui_story_5072_50720501_50_dialog_content = "Nesse sentido, a presença e o testemunho dela na verdade a tornam a principal suspeita!",
  ui_story_5072_50720501_51_dialog_content = "Não me diga que isso é tudo uma armação da sua guilda para arruinar nosso nome?",
  ui_story_5072_50720501_52_dialog_content = "Você sabe algo sobre a senhora da Guilda Ziyun?",
  ui_story_5072_50720501_53_dialog_content = "Não. Mas, dado o que acabou de ser dito, pode haver algo peculiar sobre ela.",
  ui_story_5072_50720501_54_dialog_content = "Só saí por um curto período e já estou sendo acusado.",
  ui_story_5072_50720501_55_dialog_content = "Está me chamando de suspeito?",
  ui_story_5072_50720501_56_dialog_content = "Uau, a presença... Só poderia ser de uma dama elegante!",
  ui_story_5072_50720501_57_dialog_content = "É uma suposição razoável!",
  ui_story_5072_50720501_58_dialog_content = "Por que você não faz uma enquete e vê se isso foi justo ou não.",
  ui_story_5072_50720501_59_dialog_content = "Certamente. Alguém, por favor, se adiante se também suspeitar de mim.",
  ui_story_5072_50720501_60_dialog_content = "...",
  ui_story_5072_50720501_61_dialog_content = "Como não há mais comentários, vou descrever meu encontro da noite passada novamente.",
  ui_story_5072_50720501_62_dialog_content = "Ao contrário do jovem mestre que se abaixa e se esconde, sem vontade de testemunhar.",
  ui_story_5072_50720501_63_dialog_content = "Por que você... Tudo bem, por que você não se explica então?",
  ui_story_5072_50720501_64_dialog_content = "Primeiro, vim para Twin Pavilions Bay para procurar heranças de família perdidas, então não era suficiente passar pelos canais normais.",
  ui_story_5072_50720501_65_dialog_content = "Mas as noites na Baía atraíam um público mais diversificado do que eu imaginava...",
  ui_story_5072_50720501_66_dialog_content = "Finalmente rastreamos o colecionador com grande esforço apenas para sermos negados a entrada, nos forçando a vigiar a residência.",
  ui_story_5072_50720501_67_dialog_content = "E acabamos tendo alguns problemas com o Anfitrião de Vilanor, juntamente com acusações infundadas de pessoas sombrias como você.",
  ui_story_5072_50720501_68_dialog_content = "Não há lei em Twin Pavilions Bay?!",
  ui_story_5072_50720501_69_dialog_content = "...",
  ui_story_5072_50720501_70_dialog_content = "Quanto ao surgimento aterrorizante do Exército de Vilanor...",
  ui_story_5072_50720501_71_dialog_content = "Leve a sério os meus avisos e não me culpe por não ter te alertado com antecedência.",
  ui_story_5072_50720502_1_dialog_content = "E isso é o máximo da minha interação com ele.",
  ui_story_5072_50720502_2_dialog_content = "Sinta-se à vontade para fazer qualquer pergunta que você tenha agora.",
  ui_story_5072_50720502_3_dialog_content = "Mas não vou ouvir dúvidas novamente depois de hoje, ou então.",
  ui_story_5072_50720502_4_dialog_content = "...",
  ui_story_5072_50720502_5_dialog_content = "Então, há mais algum assunto que você gostaria de discutir?",
  ui_story_5072_50720502_6_dialog_content = "Bem, você foi claro e convincente. Não consigo discernir nenhuma falha na sua história agora.",
  ui_story_5072_50720502_7_dialog_content = "Parece que todas as guildas devem aprender com isso e ficar de olho no Vilanor's Host.",
  ui_story_5072_50720502_8_dialog_content = "Mas...",
  ui_story_5072_50720502_9_dialog_content = "Dê sua opinião.",
  ui_story_5072_50720502_10_dialog_content = "Vejo que você tem carregado uma caixa de instrumento musical com você, e obviamente é volumosa e inconveniente.",
  ui_story_5072_50720502_11_dialog_content = "May Posso perguntar por que você sempre mantém isso com você?",
  ui_story_5072_50720502_12_dialog_content = "!",
  ui_story_5072_50720502_13_dialog_content = "...",
  ui_story_5072_50720502_14_dialog_content = "Por que você está fazendo rodeios?",
  ui_story_5072_50720502_15_dialog_content = "Quando você ainda tem dúvidas sobre mim!",
  ui_story_5072_50720502_16_dialog_content = "Sou de Longzhou, e tais itens sofisticados são uma necessidade para os socialites viajantes de Longzhou.",
  ui_story_5072_50720502_17_dialog_content = "Além dos negócios da família, eu também esperava encontrar e compartilhar ideias com amantes da música local.",
  ui_story_5072_50720502_18_dialog_content = "Quem diria que, por mais acolhedora que Twin Pavilions Bay parecesse, não havia lugar para o meu instrumento musical!",
  ui_story_5072_50720502_19_dialog_content = "Se você deseja inspecionar, eu vou entregá-lo a você!",
  ui_story_5072_50720502_20_dialog_content = "Desculpe por duvidar de você.",
  ui_story_5072_50720502_21_dialog_content = "Como posso continuar a suspeitar quando você se explicou tão claramente?",
  ui_story_5072_50720502_22_dialog_content = "Por favor, perdoe minhas ações. May que você alcance seus objetivos em breve.",
  ui_story_5072_50720502_23_dialog_content = "Ufa... Ainda bem que acabou.",
  ui_story_5072_50720502_24_dialog_content = "Perfeição, absoluta perfeição. Ótimo trabalho, Arrie.",
  ui_story_5072_50720502_25_dialog_content = "Meu coração pulou uma batida quando você ofereceu para deixá-lo verificar a caixa.",
  ui_story_5072_50720502_26_dialog_content = "Você tomou uma decisão corajosa.",
  ui_story_5072_50720502_27_dialog_content = "Bem, não era isso que eu estava pensando.",
  ui_story_5072_50720502_28_dialog_content = "Eu estava contando com ele desistindo assim que descobrisse que não conseguia mover o caso.",
  ui_story_5072_50720502_29_dialog_content = "Isso também é verdade.",
  ui_story_5072_50720502_30_dialog_content = "No entanto, com base nas informações que acabamos de receber, tenho um palpite do que fazer a seguir.",
  ui_story_5072_50720502_31_dialog_content = "Vamos nos separar. Você continua investigando pistas no distrito comercial.",
  ui_story_5072_50720502_32_dialog_content = "Quanto a mim, vou visitar alguns velhos amigos e tentar descobrir histórias sobre o Anfitrião de Vilanor.",
  ui_story_5072_50720502_33_dialog_content = "Então vamos descobrir o resto depois que nos encontrarmos novamente.",
  ui_story_5072_50720502_34_dialog_content = "Claro. Vou fazer o meu melhor.",
  ui_story_5072_50720503_1_dialog_content = "Ei, adivinho, sua leitura estava totalmente errada.",
  ui_story_5072_50720503_2_dialog_content = "Você me disse que problemas estavam chegando há alguns dias, mas acabei ganhando algum dinheiro.",
  ui_story_5072_50720503_3_dialog_content = "Você não garantiu que estaria certo ou meu dinheiro de volta? Eu quero um reembolso!",
  ui_story_5072_50720503_4_dialog_content = "Vamos lá, senhor, não tenha tanta pressa.",
  ui_story_5072_50720503_5_dialog_content = "Se eu me lembro corretamente, sua leitura não foi exatamente favorável. Tigre Yang e Porco Yin, certo?",
  ui_story_5072_50720503_6_dialog_content = "Você ainda se lembra disso?",
  ui_story_5072_50720503_7_dialog_content = "Com certeza. Isso indica um mau presságio.",
  ui_story_5072_50720503_8_dialog_content = "Os pequenos lucros que você fez... Veio de um investimento?",
  ui_story_5072_50720503_9_dialog_content = "O retorno escasso foi apenas um símbolo em troca de sua vasta fortuna. Prossiga com cautela, para que não se encontre desprovido de tudo.",
  ui_story_5072_50720503_10_dialog_content = "Perde, perde!",
  ui_story_5072_50720503_11_dialog_content = "Tudo, tudo!",
  ui_story_5072_50720503_12_dialog_content = "Esses dois corvos seus são maus presságios, assim como você!",
  ui_story_5072_50720503_13_dialog_content = "Embora eu também admita que eles podem ser irritantes, eles são na verdade estorninhos, não corvos.",
  ui_story_5072_50720503_14_dialog_content = "Tudo bem, vidente, sua leitura pode estar errada, mas você é muito bom com histórias.",
  ui_story_5072_50720503_15_dialog_content = "A história que você contou sobre a garçonete se tornando a rainha do reino submarino foi legal. Que tal outra?",
  ui_story_5072_50720503_16_dialog_content = "Tudo bem, eu tenho outra. É sobre um espadachim amaldiçoado.",
  ui_story_5072_50720503_17_dialog_content = "Todos, reúnam-se e, por favor, me deem uma ou duas moedas se puderem.",
  ui_story_5072_50720503_18_dialog_content = "Era uma vez, havia um espadachim amaldiçoado...",
  ui_story_5072_50720503_19_dialog_content = "Quem era anêmica, sofria de crescimentos espinhosos, mas empunhava uma enorme espada!",
  ui_story_5072_50720503_20_dialog_content = "A lâmina poderia derrotar qualquer demônio e vencer qualquer inimigo.",
  ui_story_5072_50720503_21_dialog_content = "O espadachim viajou ao longo do Rio Dourado, não buscando nem fortuna nem fama...",
  ui_story_5072_50720503_22_dialog_content = "Mas em uma busca obstinada para quebrar todos os tipos de maldições estranhas.",
  ui_story_5072_50720503_23_dialog_content = "Pois ela acreditava que apenas quebrando todas as maldições do mundo, ela poderia encontrar uma maneira de se salvar.",
  ui_story_5072_50720503_24_dialog_content = "E agora, aquele espadachim veio para Twin Pavilions Bay, na foz do Rio Dourado.",
  ui_story_5072_50720503_25_dialog_content = "Ela irá derrotar a maldição e se libertar?",
  ui_story_5072_50720503_26_dialog_content = "Até a próxima!",
  ui_story_5072_50720503_27_dialog_content = "Ei, você, não pare no meio do caminho!",
  ui_story_5072_50720503_28_dialog_content = "Sim!",
  ui_story_5072_50720503_29_dialog_content = "Bem, se você quer mais, acredito que vou precisar de um pouco de motivação monetária.",
  ui_story_5072_50720503_30_dialog_content = "Monetário, monetário!",
  ui_story_5072_50720503_31_dialog_content = "Motivação, motivação!",
  ui_story_5072_50720503_32_dialog_content = "Você quer dinheiro por isso? Tô fora daqui.",
  ui_story_5072_50720503_33_dialog_content = "Espadachim amaldiçoado?",
  ui_story_5072_50720503_34_dialog_content = "Não é isso que tem acontecido ultimamente nesta cidade?",
  ui_story_5072_50720503_35_dialog_content = "Está tentando vender a história como se fosse sua? De jeito nenhum!",
  ui_story_5072_50720503_36_dialog_content = "Não, não é isso. Vocês não me pediram para contar uma história?",
  ui_story_5072_50720503_37_dialog_content = "Eu pensei que o Anfitrião de Vilanor era grotesco o suficiente para assustar a todos.",
  ui_story_5072_50720503_38_dialog_content = "Como você fez parecer uma história heroica? Há apenas uma certa liberdade criativa que você tem, sabe.",
  ui_story_5072_50720503_39_dialog_content = "Suspiro, é uma linha tênue entre o bem e o mal.",
  ui_story_5072_50720503_40_dialog_content = "O espadachim pode ser malvado hoje aos seus olhos, mas pode se tornar um herói amanhã.",
  ui_story_5072_50720503_41_dialog_content = "Sai da frente... Você! Quem deu permissão para você montar uma loja aqui?",
  ui_story_5072_50720503_42_dialog_content = "Vamos lá, estou apenas tentando ganhar a vida aqui. Por que você não pode me deixar em paz?",
  ui_story_5072_50720503_43_dialog_content = "Em primeiro lugar, é contra a lei você montar uma barraca aqui.",
  ui_story_5072_50720503_44_dialog_content = "Em segundo lugar, estamos colocando um cartaz de procurado aqui e isso tem prioridade.",
  ui_story_5072_50720503_45_dialog_content = "Se manda se sabe o que é melhor para você!",
  ui_story_5072_50720503_46_dialog_content = "Entendi. Mas deixe-me dar uma olhada nesta recompensa antes de eu ir.",
  ui_story_5072_50720503_47_dialog_content = "Hmm, Yin Dog e Yin Goat. Receio que a pessoa no cartaz não seja a que você deveria estar procurando.",
  ui_story_5072_50720503_48_dialog_content = "Isso não é da sua conta!",
  ui_story_5072_50720503_49_dialog_content = "Tudo bem, tudo bem, eu vejo que nenhuma boa ação fica impune. Adeus, então.",
  ui_story_5072_50720601_1_dialog_content = "As ruas do lado leste parecem mais movimentadas do que o habitual hoje.",
  ui_story_5072_50720601_2_dialog_content = "O que é isso...?",
  ui_story_5072_50720601_3_dialog_content = "Um cartaz de procurado para o Anfitrião de Vilanor?!",
  ui_story_5072_50720601_4_dialog_content = "Não é à toa que as pessoas têm falado sobre alguém com uma espada grande e estranha...",
  ui_story_5072_50720601_5_dialog_content = "Tenho que ter mais cuidado e garantir que minha espada mágica não seja vista...",
  ui_story_5072_50720601_6_dialog_content = "Felizmente eu tenho a maleta. Contanto que eu aja naturalmente, ninguém deveria desconfiar de nada...",
  ui_story_5072_50720601_7_dialog_content = "Atenção, Arrie, alguém está se aproximando rápido!",
  ui_story_5072_50720601_8_dialog_content = "O quê?!",
  ui_story_5072_50720601_9_dialog_content = "Como ousa assediar uma senhora em plena luz do dia!",
  ui_story_5072_50720601_10_dialog_content = "Não há lei em Twin Pavilions Bay?",
  ui_story_5072_50720601_11_dialog_content = "Poupe-me, mocinha, poupe-me!",
  ui_story_5072_50720601_12_dialog_content = "Hã?",
  ui_story_5072_50720601_13_dialog_content = "Eu-Eu não quis dizer nada de mal de jeito nenhum!",
  ui_story_5072_50720601_14_dialog_content = "Ouvi os membros da guilda falando sobre como a mestra Ziyun é uma musicista habilidosa...",
  ui_story_5072_50720601_15_dialog_content = "Presumi que você deve ser uma senhora elegante, então pensei em oferecer o serviço da minha oficina para você.",
  ui_story_5072_50720601_16_dialog_content = "Vou recuar agora se eu te ofendi!",
  ui_story_5072_50720601_17_dialog_content = "(Ele parece comum o suficiente para ser um comerciante.)",
  ui_story_5072_50720601_18_dialog_content = "(Mas minha espada nunca errou, então eu deveria perguntar.)",
  ui_story_5072_50720601_19_dialog_content = "Ele é realmente apenas um comerciante?",
  ui_story_5072_50720601_20_dialog_content = "Bom...",
  ui_story_5072_50720601_21_dialog_content = "É possível que ele também seja um ladrão.",
  ui_story_5072_50720601_22_dialog_content = "De qualquer forma, sinto alguma hostilidade, mas nenhuma grande ameaça. Você pode ficar tranquilo.",
  ui_story_5072_50720601_23_dialog_content = "Ufa...",
  ui_story_5072_50720601_24_dialog_content = "Eles estão procurando pelo Anfitrião de Vilanor ultimamente, então devemos ter cuidado.",
  ui_story_5072_50720601_25_dialog_content = "Você esteve ao meu lado o tempo todo, espada mágica, então tente não me assustar.",
  ui_story_5072_50720601_26_dialog_content = "Você tem razão, Arrie.",
  ui_story_5072_50720601_27_dialog_content = "Mas minhas habilidades são um tanto limitadas dentro deste caso, o que também afeta meu julgamento.",
  ui_story_5072_50720601_28_dialog_content = "Não foi minha intenção causar um alarme falso. Espero que você entenda...",
  ui_story_5072_50720601_29_dialog_content = "Eu acho que sim. Provavelmente não deve ser bom ficar deitado dentro de um espaço escuro, imagino.",
  ui_story_5072_50720601_30_dialog_content = "No entanto, ainda não consigo acreditar que mesmo agora...",
  ui_story_5072_50720601_31_dialog_content = "Estamos juntos praticamente a minha vida toda.",
  ui_story_5072_50720601_32_dialog_content = "Quem poderia ter pensado que a silenciosa espada mágica de repente falaria?",
  ui_story_5072_50720601_33_dialog_content = "Bom...",
  ui_story_5072_50720601_34_dialog_content = "Sempre imaginei você como distante e sério.",
  ui_story_5072_50720601_35_dialog_content = "Até você começar a falar e realmente me fazer sentir que você não era a espada que eu conhecia.",
  ui_story_5072_50720601_36_dialog_content = "Mas sim um amigo que está sempre cuidando de mim.",
  ui_story_5072_50720601_37_dialog_content = "Sobre isso... Habilidade e personalidade nem sempre combinam.",
  ui_story_5072_50720601_38_dialog_content = "Como um espírito de espada recentemente despertado, talvez eu tenha sido influenciado por você.",
  ui_story_5072_50720601_39_dialog_content = "Eu? De jeito nenhum, eu não sou tão poderoso. É você que teve um impacto maior em mim.",
  ui_story_5072_50720601_40_dialog_content = "Não, você é realmente tão poderoso para mim.",
  ui_story_5072_50720601_41_dialog_content = "Porque tudo que eu sei, aprendi com você.",
  ui_story_5072_50720601_42_dialog_content = "Meu objetivo é informar tudo sobre esta espada e ajudá-lo a ver o mundo através de sua perspectiva.",
  ui_story_5072_50720601_43_dialog_content = "Antes, eu só podia assistir. Mas agora, finalmente posso falar e te ajudar!",
  ui_story_5072_50720601_44_dialog_content = "Espero que possamos continuar contando um com o outro e buscar esperança juntos!",
  ui_story_5072_50720601_45_dialog_content = "Uau, nunca pensei que haveria um dia em que eu ouviria encorajamento da minha espada mágica...",
  ui_story_5072_50720601_46_dialog_content = "Obrigado. Eu me sinto muito melhor agora. O sentimento é mútuo...",
  ui_story_5072_50720601_47_dialog_content = "<size=45>Pare, ladrão!</size>",
  ui_story_5072_50720601_48_dialog_content = "?!",
  ui_story_5072_50720601_49_dialog_content = "Não é aquele cara que você disse para ficar de olho antes?",
  ui_story_5072_50720601_50_dialog_content = "Ele realmente é um ladrão... Boa decisão.",
  ui_story_5072_50720601_51_dialog_content = "Na verdade, foi apenas uma observação casual...",
  ui_story_5072_50720601_52_dialog_content = "Então, o que devemos fazer agora...?",
  ui_story_5072_50720601_53_dialog_content = "Ele tentou roubar de mim e provavelmente estava mirando em você.",
  ui_story_5072_50720601_54_dialog_content = "Não podemos deixar isso passar, então vamos pegá-lo, claro.",
  ui_story_5072_50720601_55_dialog_content = "OK, vamos lá.",
  ui_story_5072_50720601_56_dialog_content = "Está lotado aqui. Eu consigo lidar com isso sozinho.",
  ui_story_5072_50720601_57_dialog_content = "Afinal, é apenas um ladrão. Eu não passei todos esses anos como mercenário à toa...",
  ui_story_5072_50720601_58_dialog_content = "Então sente-se e assista... Uh, sente-se e perceba o que eu vou fazer!",
  ui_story_5072_50720602_1_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5072_50720602_2_dialog_content = "Não te disseram para parar?",
  ui_story_5072_50720602_3_dialog_content = "É você, a senhora em quem esbarrei... Não acho que tenhamos uma rixa entre nós.",
  ui_story_5072_50720602_4_dialog_content = "Então, você não pode simplesmente me deixar ir, vendo que esta é a minha primeira ofensa?",
  ui_story_5072_50720602_5_dialog_content = "Apenas as pessoas podem dizer se esta é a sua primeira vez.",
  ui_story_5072_50720602_6_dialog_content = "Além disso, tenho quase certeza de que você estava tentando me roubar naquela época.",
  ui_story_5072_50720602_7_dialog_content = "Eu não sou do tipo que perdoa todo mundo.",
  ui_story_5072_50720602_8_dialog_content = "Ei, não é aquele ladrão que vem rondando por dias?",
  ui_story_5072_50720602_9_dialog_content = "Ladrão estúpido, vamos ver o quão rápido você pode correr agora!",
  ui_story_5072_50720602_10_dialog_content = "Muito obrigado, jovem senhora.",
  ui_story_5072_50720602_11_dialog_content = "Não mencione isso. Estou apenas fazendo o que eu deveria fazer.",
  ui_story_5072_50720602_12_dialog_content = "Ei, olha só, o ladrão foi pego, graças à senhora de Longzhou!",
  ui_story_5072_50720602_13_dialog_content = "Ela parece muito pequena e delicada para ser uma lutadora tão boa!",
  ui_story_5072_50720602_14_dialog_content = "Hum...",
  ui_story_5072_50720602_15_dialog_content = "(A multidão está aumentando e eu estou começando a me sentir um pouco...)",
  ui_story_5072_50720602_16_dialog_content = "Como um sinal da minha gratidão, gostaria de convidá-lo para a minha loja!",
  ui_story_5072_50720602_17_dialog_content = "Vou servir o melhor chá que tenho...",
  ui_story_5072_50720602_18_dialog_content = "Ai!",
  ui_story_5072_50720602_19_dialog_content = "Quem acabou de me cutucar?!",
  ui_story_5072_50720602_20_dialog_content = "O que você está dizendo? Ninguém te tocou. A senhora é a única ao seu lado!",
  ui_story_5072_50720602_21_dialog_content = "Tudo bem. Eu não vou ficar. Você deve entregar o ladrão à Guarda da Cidade...",
  ui_story_5072_50720602_22_dialog_content = "E-Eu tenho um assunto urgente para tratar, então preciso ir.",
  ui_story_5072_50720602_23_dialog_content = "Ei, espere, mocinha...",
  ui_story_5072_50720602_24_dialog_content = "Adeus!",
  ui_story_5072_50720602_25_dialog_content = "Ufa...",
  ui_story_5072_50720602_26_dialog_content = "Eu me acostumei tanto com essa fantasia, que esqueci dos espinhos em mim.",
  ui_story_5072_50720602_27_dialog_content = "Devo lembrar de manter uma distância dos outros.",
  ui_story_5072_50720602_28_dialog_content = "Desculpe...",
  ui_story_5072_50720602_29_dialog_content = "Hã? Por que você está se desculpando, Espada Mágica?",
  ui_story_5072_50720602_30_dialog_content = "Os espinhos são minha culpa por não conseguir encontrar outra maneira de curar você.",
  ui_story_5072_50720602_31_dialog_content = "Isso conta como negligência da minha parte como espírito da espada, certo?",
  ui_story_5072_50720602_32_dialog_content = "Não, como pode ser culpa sua?",
  ui_story_5072_50720602_33_dialog_content = "Por favor, não se culpe!",
  ui_story_5072_50720602_34_dialog_content = "Os espinhos salvaram minha vida e não me trouxeram sofrimento adicional... Não tenho do que reclamar.",
  ui_story_5072_50720602_35_dialog_content = "Eu só quero quebrar a maldição e deixar minha família em paz.",
  ui_story_5072_50720602_36_dialog_content = "Arrie...",
  ui_story_5072_50720602_37_dialog_content = "E veja, até o problema de não poder usar vestidos bonitos não é uma questão em Twin Pavilions Bay.",
  ui_story_5072_50720602_38_dialog_content = "Sim, o vestido fica muito bonito em você.",
  ui_story_5072_50720602_39_dialog_content = "Você também, Espada Mágica...? Ok, chega disso.",
  ui_story_5072_50720602_40_dialog_content = "(Francamente, eu também gosto assim...)",
  ui_story_5072_50720602_41_dialog_content = "Agora não é hora de aproveitar a vida de uma socialite. Temos que ir encontrar a Senhorita Armilla antes que estejamos atrasados.",
  ui_story_5072_50720602_42_dialog_content = "Como mercenário, devo permanecer vigilante o tempo todo.",
  ui_story_5072_50720701_1_dialog_content = "Estou aqui, Arrie.",
  ui_story_5072_50720701_2_dialog_content = "?!",
  ui_story_5072_50720701_3_dialog_content = "Senhorita Armilla! Ufa, graças a Deus, achei que ia me atrasar.",
  ui_story_5072_50720701_4_dialog_content = "Tudo bem. Acabei de chegar aqui também, e com boas notícias para completar.",
  ui_story_5072_50720701_5_dialog_content = "Tudo graças às pistas que você conseguiu.",
  ui_story_5072_50720701_6_dialog_content = "Você está se referindo ao Anfitrião de Vilanor?",
  ui_story_5072_50720701_7_dialog_content = "Sim. O que vale a pena comemorar é o fato de eu ter descoberto o maior mistério que o envolve.",
  ui_story_5072_50720701_8_dialog_content = "Especificamente, como um garçom normal poderia ser poderoso demais para você lidar.",
  ui_story_5072_50720701_9_dialog_content = "A espada é a razão de tudo isso!",
  ui_story_5072_50720701_10_dialog_content = "Os membros do Red Shell disseram que já viram a espada antes. É uma lâmina requintada de Longzhou.",
  ui_story_5072_50720701_11_dialog_content = "A espada é definitivamente encantada e exatamente a coisa que eu quero recuperar!",
  ui_story_5072_50720701_12_dialog_content = "Esta história também reflete como as engrenagens se interligam dentro de um dispositivo...",
  ui_story_5072_50720701_13_dialog_content = "Uma espada arcano?",
  ui_story_5072_50720701_14_dialog_content = "Mas isso não exigiria alta proficiência do usuário para empunhar?",
  ui_story_5072_50720701_15_dialog_content = "Boa pergunta, Arrie, e é isso que torna a espada única.",
  ui_story_5072_50720701_16_dialog_content = "Se a sua espada foi especificamente forjada para ser manejada apenas por você...",
  ui_story_5072_50720701_17_dialog_content = "Então, esta espada foi especificamente forjada para qualquer um usar.",
  ui_story_5072_50720701_18_dialog_content = "Então, até mesmo aqueles sem habilidades de luta poderiam se defender.",
  ui_story_5072_50720701_19_dialog_content = "Mas obviamente, isso poderia causar um problema muito mais aterrorizante...",
  ui_story_5072_50720701_20_dialog_content = "Na mão de um fraco, é proteção. Mas na mão de um bruto...",
  ui_story_5072_50720701_21_dialog_content = "Sim, isso a tornaria uma arma de assassinato.",
  ui_story_5072_50720701_22_dialog_content = "Entendo...",
  ui_story_5072_50720701_23_dialog_content = "Essa é uma espada lamentável e explorada.",
  ui_story_5072_50720701_24_dialog_content = "Seu criador provavelmente estava muito imerso em suas visões para prever algo assim...",
  ui_story_5072_50720701_25_dialog_content = "Eu já relatei a situação e os riscos aos Lins e ao quartel-general.",
  ui_story_5072_50720701_26_dialog_content = "Então eles estariam cientes do Anfitrião de Vilanor e dos possíveis mentores por trás disso.",
  ui_story_5072_50720701_27_dialog_content = "Os ataques noturnos não devem se tornar uma ocorrência regular novamente.",
  ui_story_5072_50720701_28_dialog_content = "Isso explica o pôster de recompensa que eu vi. Você os alertou sobre isso.",
  ui_story_5072_50720701_29_dialog_content = "Devo aumentar meu esforço para não ficar para trás!",
  ui_story_5072_50720701_30_dialog_content = "Vamos lá, não seja tão tenso.",
  ui_story_5072_50720701_31_dialog_content = "Eu não poderia ter feito isso sem o seu esforço.",
  ui_story_5072_50720701_32_dialog_content = "Você só precisa continuar fazendo o que tem feito. Visitaremos nosso próximo contato nos próximos dias.",
  ui_story_5072_50720701_33_dialog_content = "Mas não vamos bater nos arbustos e assustar a cobra.",
  ui_story_5072_50720701_34_dialog_content = "Que cobra...?",
  ui_story_5072_50720701_35_dialog_content = "Cobra?",
  ui_story_5072_50720701_36_dialog_content = "Ah, isso é uma figura de fala, mas eu conheço um lugar para onde devo te levar agora.",
  ui_story_5072_50720701_37_dialog_content = "Aonde?",
  ui_story_5072_50720701_38_dialog_content = "Um boticário, com todas as ervas medicinais sob o sol e um fitoterapeuta de primeira linha.",
  ui_story_5072_50720701_39_dialog_content = "Permita-me levar minha senhora lá e ser curada enquanto isso.",
  ui_story_5072_50720701_40_dialog_content = "Ah, hum...",
  ui_story_5072_50720701_41_dialog_content = "Desculpe, eu me deparei com um ladrão e não pude me conter.",
  ui_story_5072_50720701_42_dialog_content = "Não há nada para se sentir culpado. Isso te faz mais do que um mercenário. Isso te faz um herói.",
  ui_story_5072_50720701_43_dialog_content = "Você me lisonjeou. Estou preocupado que esta fantasia que você comprou para mim possa ser danificada...",
  ui_story_5072_50720701_44_dialog_content = "Não se preocupe com isso. As coisas se danificam o tempo todo. Sem mencionar que há um alfaiate perto da farmácia.",
  ui_story_5072_50720701_45_dialog_content = "Além disso, temos muitos suprimentos em reserva.",
  ui_story_5072_50720701_46_dialog_content = "Você é uma socialite de Longzhou, afinal, e merece mais de um traje.",
  ui_story_5072_50720701_47_dialog_content = "Venha, vamos às compras na Rua Chunxi.",
  ui_story_5072_50720701_48_dialog_content = "Tá, já entendi.",
  ui_story_5072_50720701_49_dialog_content = "Bem-vindo! Como posso ajudar... Ah, é você.",
  ui_story_5072_50720701_50_dialog_content = "Você está tentando dizer que eu não sou bem-vindo?",
  ui_story_5072_50720701_51_dialog_content = "O mestre não está hoje. Posso te dar um desconto regular se você quiser os itens básicos para fazer bebidas de ervas. Não me dificulte.",
  ui_story_5072_50720701_52_dialog_content = "Você disse isso como se eu me aproveitasse de você todas as vezes.",
  ui_story_5072_50720701_53_dialog_content = "Bem, você sempre encontrou uma maneira de pechinchar tudo por um valor bem menor.",
  ui_story_5072_50720701_54_dialog_content = "É muito mais fácil para mim simplesmente me livrar de você o mais rápido possível.",
  ui_story_5072_50720701_55_dialog_content = "Tudo bem, você mostrou seu ponto de vista. Eu não vim por nada de especial hoje.",
  ui_story_5072_50720701_56_dialog_content = "E não sou eu quem precisa de atendimento médico. É a senhora aqui ao meu lado.",
  ui_story_5072_50720701_57_dialog_content = "A senhora está acostumada com coisas finas, então certifique-se de trazer o estoque de qualidade!",
  ui_story_5072_50720701_58_dialog_content = "Não vou economizar com um recém-chegado.",
  ui_story_5072_50720701_59_dialog_content = "Estragar a minha própria reputação não é um grande problema, mas arruinar a do meu mestre é.",
  ui_story_5072_50720701_60_dialog_content = "Óh, e o paciente...",
  ui_story_5072_50720701_61_dialog_content = "E eu?",
  ui_story_5072_50720701_62_dialog_content = "Ei, posso falar com você em particular?",
  ui_story_5072_50720701_63_dialog_content = "Tudo bem. Apenas fale o que está em sua mente.",
  ui_story_5072_50720701_64_dialog_content = "Os ferimentos nesta senhora não são normais, mas uma condição crônica ao longo de muitos anos...",
  ui_story_5072_50720701_65_dialog_content = "Ele incorporou um ódio intenso.",
  ui_story_5072_50720701_66_dialog_content = "Provavelmente é um milagre ela ainda estar viva com aquilo.",
  ui_story_5072_50720701_67_dialog_content = "Quem é ela...",
  ui_story_5072_50720701_68_dialog_content = "É rude seguir essa linha de questionamento.",
  ui_story_5072_50720701_69_dialog_content = "Ok, entendi isso.",
  ui_story_5072_50720701_70_dialog_content = "Mas não é um problema que a medicina normal possa resolver, além de aliviar um pouco a dor na pele.",
  ui_story_5072_50720701_71_dialog_content = "Desculpe, mocinha.",
  ui_story_5072_50720701_72_dialog_content = "Está bem. Obrigado pelo diagnóstico.",
  ui_story_5072_50720701_73_dialog_content = "Estou acostumada a ter este corpo, e sou muito grata pelas roupas e medicamentos.",
  ui_story_5072_50720701_74_dialog_content = "A cultura de Longzhou realmente é nada menos que incrível.",
  ui_story_5072_50720701_75_dialog_content = "Mas você não é de Longzhou...?",
  ui_story_5072_50720701_76_dialog_content = "Não se preocupe com isso e prepare as ervas! A propósito, também preciso de uma lista.",
  ui_story_5072_50720701_77_dialog_content = "Você não acabou de prometer que não iria pechinchar ou se aproveitar de mim?",
  ui_story_5072_50720701_78_dialog_content = "Estou fazendo isso apenas porque você me trouxe um novo paciente... Tudo bem, que tipo de lista?",
  ui_story_5072_50720701_79_dialog_content = "Nomes das vítimas esfaqueadas recentemente. Quanto mais detalhes, melhor.",
  ui_story_5072_50720701_80_dialog_content = "...",
  ui_story_5072_50720701_81_dialog_content = "Tudo bem, mas reunir a lista e as ervas vai levar algum tempo.",
  ui_story_5072_50720701_82_dialog_content = "Em troca, por que você não cuida dos ratos que vêm das águas?",
  ui_story_5072_50720701_83_dialog_content = "Ratos? Não deveria estar nos servindo chá em vez disso?",
  ui_story_5072_50720701_84_dialog_content = "Absolutamente... NÃO!",
  ui_story_5072_50720702_1_dialog_content = "Conseguimos o remédio, novo uniforme e, o mais importante, a lista.",
  ui_story_5072_50720702_2_dialog_content = "Tudo certamente corre bem quando você está por perto, Arrie.",
  ui_story_5072_50720702_3_dialog_content = "Mas eu não fiz nada... Na verdade, você fez tudo por mim.",
  ui_story_5072_50720702_4_dialog_content = "Não, não, você se apresentou excelentemente como de costume.",
  ui_story_5072_50720702_5_dialog_content = "Sério?",
  ui_story_5072_50720702_6_dialog_content = "Caso contrário, o aprendiz teria me expulsado da loja.",
  ui_story_5072_50720702_7_dialog_content = "Falaremos sobre isso mais tarde. Venha ver a lista.",
  ui_story_5072_50720702_8_dialog_content = "Você tem muito mais experiência com lâminas do que eu, então quero sua opinião.",
  ui_story_5072_50720702_9_dialog_content = "Tá bom...",
  ui_story_5072_50720702_10_dialog_content = "Hum...",
  ui_story_5072_50720702_11_dialog_content = "É extremamente detalhado. Não é à toa que ele é o seu informante de confiança.",
  ui_story_5072_50720702_12_dialog_content = "Esse aprendiz também é excepcional.",
  ui_story_5072_50720702_13_dialog_content = "Ele pode parecer jovem, mas é bastante conhecedor e um ótimo médico.",
  ui_story_5072_50720702_14_dialog_content = "Ele fala sobre salvar vidas e ajudar os doentes o tempo todo. Ele está determinado a curar o todo o mundo.",
  ui_story_5072_50720702_15_dialog_content = "Curar o quê?",
  ui_story_5072_50720702_16_dialog_content = "Cure você, minha senhora.",
  ui_story_5072_50720702_17_dialog_content = "Esqueça, estamos divagando. Apenas verifique o resto da lista.",
  ui_story_5072_50720702_18_dialog_content = "Tá bom.",
  ui_story_5072_50720702_19_dialog_content = "Desta lista, vejo que vários marinheiros que trabalhavam no cais foram esfaqueados recentemente.",
  ui_story_5072_50720702_20_dialog_content = "Eles não conseguiram descrever o que aconteceu com eles além de convulsões, desmaios ou uma aura negra ao redor de seus rostos.",
  ui_story_5072_50720702_21_dialog_content = "Isso é muito parecido com o que eu vi na casa daquele colecionador.",
  ui_story_5072_50720702_22_dialog_content = "O Anfitrião de Vilanor provavelmente está por trás de tudo isso. Então, talvez ele esteja ativo naquela parte da cidade?",
  ui_story_5072_50720702_23_dialog_content = "Estamos na mesma página.",
  ui_story_5072_50720702_24_dialog_content = "Os produtos de Longzhou geralmente são enviados por água.",
  ui_story_5072_50720702_25_dialog_content = "Convém perguntarmos aos marinheiros que navegam pelo Rio Dourado.",
  ui_story_5072_50720702_26_dialog_content = "Já que estamos seguindo esse caminho, por que não miramos em um peixe grande?",
  ui_story_5072_50720702_27_dialog_content = "Claro. Então, qual é o nosso próximo alvo?",
  ui_story_5072_50720702_28_dialog_content = "A Galera do Rio Áureo é preferida pelos comerciantes ricos.",
  ui_story_5072_50720702_29_dialog_content = "Devo me esgueirar?",
  ui_story_5072_50720702_30_dialog_content = "Não-não. Não se esqueça que você é um socialite de Longzhou agora.",
  ui_story_5072_50720702_31_dialog_content = "É natural que você contrate alguns funcionários e chegue lá em um iate.",
  ui_story_5072_50720702_32_dialog_content = "Isso é necessário?",
  ui_story_5072_50720702_33_dialog_content = "Claro. Se você conseguir entrar, isso significa que estamos perto da fonte do mercado negro.",
  ui_story_5072_50720702_34_dialog_content = "E quem quer que seja o Anfitrião de Vilanor trabalha para alguém rico ou prestigioso.",
  ui_story_5072_50720702_35_dialog_content = "Dado que a galeria é um ponto de encontro da alta sociedade, a furtividade funciona tão bem quanto procurar uma agulha no palheiro.",
  ui_story_5072_50720702_36_dialog_content = "É melhor para nós oferecer pistas ou riquezas e atrair a cobra para fora.",
  ui_story_5072_50720702_37_dialog_content = "Atraia a cobra para fora...",
  ui_story_5072_50720702_38_dialog_content = "Algum problema com isso?",
  ui_story_5072_50720702_39_dialog_content = "Tenho a sensação de que você tem um carinho por cobras.",
  ui_story_5072_50720702_40_dialog_content = "Pois é...",
  ui_story_5072_50720703_1_dialog_content = "...",
  ui_story_5072_50720703_2_dialog_content = "Arram, o dono está?",
  ui_story_5072_50720703_3_dialog_content = "Aqui vou eu... Ei, o que posso fazer por você, jovem senhorita?",
  ui_story_5072_50720703_4_dialog_content = "Este é o navio que vai me levar para a Cozinha do Rio de Ouro?",
  ui_story_5072_50720703_5_dialog_content = "Você veio ao lugar certo. É o veículo mais rápido para isso.",
  ui_story_5072_50720703_6_dialog_content = "No entanto...",
  ui_story_5072_50720703_7_dialog_content = "Há algum problema?",
  ui_story_5072_50720703_8_dialog_content = "Patrocinadores ricos e suas festas costumam optar por fretar um navio para seus eventos.",
  ui_story_5072_50720703_9_dialog_content = "Vai ser uma espera para os passageiros regulares.",
  ui_story_5072_50720703_10_dialog_content = "Como ousa insinuar que eu não posso pagar pelo seu serviço!",
  ui_story_5072_50720703_11_dialog_content = "Não consigo acreditar como as pessoas são rudes em Twin Pavilions Bay...",
  ui_story_5072_50720703_12_dialog_content = "Não-não, não foi isso que eu quis dizer.",
  ui_story_5072_50720703_13_dialog_content = "Você está vestido com elegância, mas completamente sozinho.",
  ui_story_5072_50720703_14_dialog_content = "Há muitos operadores inescrupulosos neste cais que buscam apenas lucros.",
  ui_story_5072_50720703_15_dialog_content = "Mas apostamos nossa reputação na justiça e confiança.",
  ui_story_5072_50720703_16_dialog_content = "Além de lhe dar um preço razoável, posso encontrar uma tripulação confiável e segura.",
  ui_story_5072_50720703_17_dialog_content = "Temos um acordo?",
  ui_story_5072_50720703_18_dialog_content = "Eu gosto de como você pensa.",
  ui_story_5072_50720703_19_dialog_content = "Não me importo muito com nada, exceto atitude.",
  ui_story_5072_50720703_20_dialog_content = "Faça o que você tem que fazer.",
  ui_story_5072_50720703_21_dialog_content = "Eu vou começar imediatamente.",
  ui_story_5072_50720703_22_dialog_content = "Tenho um trabalho para vocês, marinheiros!",
  ui_story_5072_50720703_23_dialog_content = "Sim!",
  ui_story_5072_50720801_1_dialog_content = "A cabine está confortável para você, minha senhora?",
  ui_story_5072_50720801_2_dialog_content = "É adequado o suficiente.",
  ui_story_5072_50720801_3_dialog_content = "Os remadores darão tudo de si para levar você lá a tempo!",
  ui_story_5072_50720801_4_dialog_content = "Se você pudesse oferecer um pequeno incentivo, poderíamos ir ainda mais rápido...",
  ui_story_5072_50720801_5_dialog_content = "Bem, a velocidade não é tudo, e não estou certo se o seu navio foi construído de forma suficiente para isso.",
  ui_story_5072_50720801_6_dialog_content = "Isso não deveria ser uma preocupação.",
  ui_story_5072_50720801_7_dialog_content = "Nossa tripulação tem uma dúzia de anos de experiência. Sua segurança está garantida.",
  ui_story_5072_50720801_8_dialog_content = "Não é uma preocupação?",
  ui_story_5072_50720801_9_dialog_content = "Você acha que eu não sei que muitos marinheiros foram feridos pelo Anfitrião de Vilanor recentemente?",
  ui_story_5072_50720801_10_dialog_content = "Eu presumiria que atualmente há uma escassez de pessoas confiáveis.",
  ui_story_5072_50720801_11_dialog_content = "Uau, você tem boas fontes.",
  ui_story_5072_50720801_12_dialog_content = "Mas o que você não percebe é que a Baía nunca está em falta de marinheiros.",
  ui_story_5072_50720801_13_dialog_content = "E o problema do Vilanor's Host não causou nenhum impacto nisso.",
  ui_story_5072_50720801_14_dialog_content = "Nem um amassado? Então você não está preocupado com ele voltando e arruinando os negócios no cais?",
  ui_story_5072_50720801_15_dialog_content = "Não se preocupe, minha senhora. Ele não se mostrou novamente desde aquela noite.",
  ui_story_5072_50720801_16_dialog_content = "O verdadeiro problema por trás de tudo isso é, bem, os figurões despejando coisas no mercado negro.",
  ui_story_5072_50720801_17_dialog_content = "Muitos deles lidam com piratas ou criminosos.",
  ui_story_5072_50720801_18_dialog_content = "Eles podem fazer o que quiserem, desde que a guilda faça vista grossa, e dificultem para nós, negócios legítimos.",
  ui_story_5072_50720801_19_dialog_content = "O navio mais novo no Rio Dourado foi comprado por um daqueles figurões.",
  ui_story_5072_50720801_20_dialog_content = "Dizem que ele também é dono daquela cozinha sofisticada.",
  ui_story_5072_50720801_21_dialog_content = "Suspirar...",
  ui_story_5072_50720801_22_dialog_content = "O que há para suspirar?",
  ui_story_5072_50720801_23_dialog_content = "Para mim, o navio dele é muito inferior ao dos Lins e não é tão bom.",
  ui_story_5072_50720801_24_dialog_content = "Oh, minha senhora. Estes são apenas navios de passageiros. Como eles poderiam rivalizar com os cargueiros oceânicos dos Lins?",
  ui_story_5072_50720801_25_dialog_content = "Mas para pequenos barcos como o meu, ainda está fora do nosso alcance.",
  ui_story_5072_50720801_26_dialog_content = "Eles não podiam se opor aos Lins, mas certamente têm o suficiente para nos provocar, os pequenos.",
  ui_story_5072_50720801_27_dialog_content = "Como eles estão fazendo isso?",
  ui_story_5072_50720801_28_dialog_content = "Dinheiro de proteção, é claro; supostamente para manter nossos barcos seguros dos Eclipsitas.",
  ui_story_5072_50720801_29_dialog_content = "Acabamos pagando cada vez mais e ainda assim não vemos um Eclipsite a menos.",
  ui_story_5072_50720801_30_dialog_content = "Estou começando a pensar que eles estão em conluio!",
  ui_story_5072_50720801_31_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5072_50720801_32_dialog_content = "O que foi isso? Não me diga que nos deparamos com outro barco em plena luz do dia!",
  ui_story_5072_50720801_33_dialog_content = "Não se preocupe, minha senhora. É uma situação menor, tenho certeza. Deixe-me dar uma olhada.",
  ui_story_5072_50720801_34_dialog_content = "Cuidado, Arrie. Eclipsitas se aproximando.",
  ui_story_5072_50720801_35_dialog_content = "Eclipsitas à espreita no Rio Dourado...?",
  ui_story_5072_50720801_36_dialog_content = "Ei, não chegue mais perto... Ah—",
  ui_story_5072_50720801_37_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_5072_50720801_38_dialog_content = "Precisamos salvá-la.",
  ui_story_5072_50720801_39_dialog_content = "Eu sei. Me dê uma mão, Espada Mágica.",
  ui_story_5072_50720802_1_dialog_content = "Aguente firme!",
  ui_story_5072_50720802_2_dialog_content = "Ah, obrigado...",
  ui_story_5072_50720802_3_dialog_content = "Arf, arf...",
  ui_story_5072_50720802_4_dialog_content = "Obrigado pela ajuda! Esses Eclipsitas são terríveis. Devemos voltar agora...",
  ui_story_5072_50720802_5_dialog_content = "Ei, para onde foram os Eclipsitas?",
  ui_story_5072_50720802_6_dialog_content = "Eu me desfiz de todos eles.",
  ui_story_5072_50720802_7_dialog_content = "Minha nossa! Você fez isso tudo sozinho?!",
  ui_story_5072_50720802_8_dialog_content = "Obrigado! Meu navio, minha vida, meu tudo estaria perdido sem você!",
  ui_story_5072_50720802_9_dialog_content = "De nada, e não vamos voltar atrás. Ainda estou contando com você para me levar até a cozinha.",
  ui_story_5072_50720802_10_dialog_content = "Sim, sim, claro. É só...",
  ui_story_5072_50720802_11_dialog_content = "Você luta surpreendentemente bem para uma jovem delicada, minha senhora.",
  ui_story_5072_50720802_12_dialog_content = "...",
  ui_story_5072_50720802_13_dialog_content = "E não é um instrumento musical dentro da caixa...",
  ui_story_5072_50720802_14_dialog_content = "Mas uma grande espada negra, exatamente como a que é rumoreada para—",
  ui_story_5072_50720802_15_dialog_content = "Não, não, quero dizer, é certamente uma experiência reveladora.",
  ui_story_5072_50720802_16_dialog_content = "...",
  ui_story_5072_50720802_17_dialog_content = "Mas, uh, você fez perguntas sobre o Anfitrião de Vilanor assim que embarcou...",
  ui_story_5072_50720802_18_dialog_content = "O que você quer chegar?",
  ui_story_5072_50720802_19_dialog_content = "Nada!",
  ui_story_5072_50720802_20_dialog_content = "Você salvou minha vida e aqui estou eu duvidando de você. Isso não está certo...",
  ui_story_5072_50720802_21_dialog_content = "Como você pode ser tão brutal, impiedoso Anfitrião de Vilanor, certo?",
  ui_story_5072_50720802_22_dialog_content = "É claro que não!",
  ui_story_5072_50720802_23_dialog_content = "Esta espada... é uma relíquia de família! Estou levando-a para a galeria para avaliação.",
  ui_story_5072_50720802_24_dialog_content = "Eu não deveria mostrar, mas a situação era extrema...",
  ui_story_5072_50720802_25_dialog_content = "Você será pago integralmente pelo seu serviço e sua segurança está garantida pelo resto desta viagem.",
  ui_story_5072_50720802_26_dialog_content = "Apenas se concentre em me levar ao meu destino!",
  ui_story_5072_50720802_27_dialog_content = "S-Claro! Por favor, sente-se na sua cabine e estaremos lá em breve!",
  ui_story_5072_50720901_1_dialog_content = "Aqui estamos nós! A cozinha, minha senhora.",
  ui_story_5072_50720901_2_dialog_content = "Apenas suba e alguém estará lá para recebê-lo.",
  ui_story_5072_50720901_3_dialog_content = "Acho que isso foi desnecessário, já que você deve conhecer os protocolos muito melhor do que eu.",
  ui_story_5072_50720901_4_dialog_content = "Está bem. Obrigado pelas direções.",
  ui_story_5072_50720901_5_dialog_content = "Então este é o Galeão do Rio Dourado... Definitivamente um lugar muito animado.",
  ui_story_5072_50720901_6_dialog_content = "Ou talvez mais precisamente, uma mistura variada? Eu sinto muitas coisas diferentes.",
  ui_story_5072_50720901_7_dialog_content = "A partir de agora, não posso confirmar se o Anfitrião de Vilanor tem algo a ver com aqui.",
  ui_story_5072_50720901_8_dialog_content = "Entendi. Obrigado, vou tomar cuidado.",
  ui_story_5072_50720901_9_dialog_content = "E eu também fiz a lição de casa antes de vir.",
  ui_story_5072_50720901_10_dialog_content = "O que você disse sobre o Vilanor controlando sombras e energia, Arrie...",
  ui_story_5072_50720901_11_dialog_content = "A minha suposição é que ele pode deixar vestígios em itens específicos, como utensílios tocados.",
  ui_story_5072_50720901_12_dialog_content = "As antiguidades animadas emanando uma aura negra...",
  ui_story_5072_50720901_13_dialog_content = "Eles poderiam ter sido encantados pelo Vilanor.",
  ui_story_5072_50720901_14_dialog_content = "É algum tipo de assinatura?",
  ui_story_5072_50720901_15_dialog_content = "Nesse caso, a reunião na Galeria do Rio Dourado é muito mais do que aparenta.",
  ui_story_5072_50720901_16_dialog_content = "O que os olhos veem...?",
  ui_story_5072_50720901_17_dialog_content = "Sim. Se o Anfitrião de Vilanor é o executor exclusivo para o cérebro...",
  ui_story_5072_50720901_18_dialog_content = "Ele pode muito bem tentar nos superar nas relíquias de Longzhou que foram vendidas.",
  ui_story_5072_50720901_19_dialog_content = "Elimine pistas para que ninguém possa seguir.",
  ui_story_5072_50720901_20_dialog_content = "Afinal, ele tem trabalhado em Twin Pavilions Bay por um longo tempo.",
  ui_story_5072_50720901_21_dialog_content = "Nenhum estranho pode entender o quão profundo isso vai, não importa que apoio dos Lins e da sede eles tenham.",
  ui_story_5072_50720901_22_dialog_content = "Depois que passar e for esquecido, ele pode ressurgir no mercado negro novamente.",
  ui_story_5072_50720901_23_dialog_content = "Então, você acreditou que o Anfitrião de Vilanor estaria na cozinha?!",
  ui_story_5072_50720901_24_dialog_content = "Sim, e provavelmente quem vendeu a espada para Twin Pavilions Bay também. Eu preciso confirmar isso...",
  ui_story_5072_50720901_25_dialog_content = "Obrigado, senhoras e senhores, por reservarem um tempo em suas agendas ocupadas para embarcarem no meu Gold River Galley.",
  ui_story_5072_50720901_26_dialog_content = "Temos novos colecionáveis para você avaliar e comprar. Sinta-se à vontade para sugerir um preço.",
  ui_story_5072_50720901_27_dialog_content = "Mas eu tenho um pedido pessoal que gostaria que todos vocês ajudassem...",
  ui_story_5072_50720901_28_dialog_content = "Perdi uma relíquia preciosa recentemente. É uma espada arcano do exterior...",
  ui_story_5072_50720901_29_dialog_content = "...!!!",
  ui_story_5072_50720901_30_dialog_content = "A espada é incrivelmente intrincada, pela qual gastei uma fortuna para adquirir.",
  ui_story_5072_50720901_31_dialog_content = "Infelizmente, eu nunca cheguei a brandir antes de perdê-lo. Portanto...",
  ui_story_5072_50720901_32_dialog_content = "Tive que antecipar este encontro na esperança de solicitar suas sugestões.",
  ui_story_5072_50720901_33_dialog_content = "...",
  ui_story_5072_50720901_34_dialog_content = "<size=30>Espada Arcana? Não seria essa a forma original do Vilanor que a Senhorita Armilla descreveu?</size>",
  ui_story_5072_50720901_35_dialog_content = "<size=30>Eu tenho que sondar um pouco!</size>",
  ui_story_5072_50720901_36_dialog_content = "Senhor, você ouviu falar do recente esfaqueamento pelo Vilanor's Host em Twin Pavilions Bay?",
  ui_story_5072_50720901_37_dialog_content = "Você está se referindo ao incidente do colecionador de Lumopolis? Eu ouvi uma coisa ou duas.",
  ui_story_5072_50720901_38_dialog_content = "Mas o que ele tem a ver com minha espada arcana?",
  ui_story_5072_50720901_39_dialog_content = "Você perdeu a espada apenas para ter um espadachim cruel aparecendo em Twin Pavilions Bay.",
  ui_story_5072_50720901_40_dialog_content = "Se ele estivesse usando sua espada, você não seria de certa forma responsável também?",
  ui_story_5072_50720901_41_dialog_content = "Minha senhora, minha espada é apenas uma peça de coleção.",
  ui_story_5072_50720901_42_dialog_content = "Comprei por um preço alto apenas por curiosidade. Eu sou a vítima na perda.",
  ui_story_5072_50720901_43_dialog_content = "E que o Anfitrião de Vilanor só machuca as pessoas porque ele mesmo é malvado.",
  ui_story_5072_50720901_44_dialog_content = "Não faria diferença se ele usasse uma espada arcana, uma espadinha ou uma espada larga, você entende?",
  ui_story_5072_50720901_45_dialog_content = "É verdade...?",
  ui_story_5072_50720901_46_dialog_content = "Lá vem.",
  ui_story_5072_50720901_47_dialog_content = "Tão insuportável a dor e o desprezo... O que ele passou...?",
  ui_story_5072_50720901_48_dialog_content = "Do antigo poder interior nasceu a espada amaldiçoada...",
  ui_story_5072_50720901_49_dialog_content = "O mal é provavelmente além de qualquer coisa que você possa imaginar.",
  ui_story_5072_50720901_50_dialog_content = "Ou você pretende rastrear todos que conhecem o paradeiro do Anfitrião de Vilanor...",
  ui_story_5072_50720901_51_dialog_content = "E removê-los todos para encobrir seus próprios rastros?",
  ui_story_5072_50720901_52_dialog_content = "Por que você está me difamando? Quem é você? Não me lembro de ter te convidado!",
  ui_story_5072_50720901_53_dialog_content = "Guardas, venham expulsar essa mulher mentirosa do local!",
  ui_story_5072_50720901_54_dialog_content = "Onde estão os guardas?",
  ui_story_5072_50720901_55_dialog_content = "Algo está errado!",
  ui_story_5072_50720901_56_dialog_content = "...",
  ui_story_5072_50721001_1_dialog_content = "Roaaaar—",
  ui_story_5072_50721001_2_dialog_content = "Quem é você? Como ousa se intrometer!",
  ui_story_5072_50721001_3_dialog_content = "Espere, essa não é a minha espada arcana que você está segurando?!",
  ui_story_5072_50721001_4_dialog_content = "Você não veio aqui só para me devolver isso, veio?",
  ui_story_5072_50721001_5_dialog_content = "É o Anfitrião de Vilanor! Ele está aqui! Eu sabia que o dono da galera estava por trás disso...",
  ui_story_5072_50721001_6_dialog_content = "Não, o interesse dele na espada parecia inocente o suficiente e ele está inconsciente da ameaça que o Anfitrião de Vilanor representa.",
  ui_story_5072_50721001_7_dialog_content = "Mas o que o Anfitrião de Vilanor está fazendo aqui?",
  ui_story_5072_50721001_8_dialog_content = "Vingança...",
  ui_story_5072_50721001_9_dialog_content = "Vingança?",
  ui_story_5072_50721001_10_dialog_content = "Pare! O que você quer? Basta escolher qualquer coisa aqui e será seu!",
  ui_story_5072_50721001_11_dialog_content = "Eu... quero... você...",
  ui_story_5072_50721001_12_dialog_content = "O quê...?",
  ui_story_5072_50721001_13_dialog_content = "Cuidado!",
  ui_story_5072_50721001_14_dialog_content = "Eu quero que você morra!",
  ui_story_5072_50721001_15_dialog_content = "Vuuush—!",
  ui_story_5072_50721001_16_dialog_content = "Argh!",
  ui_story_5072_50721001_17_dialog_content = "Anfitrião de Vilanor! É o anfitrião de Vilanor!",
  ui_story_5072_50721001_18_dialog_content = "O que eu deveria fazer agora...?",
  ui_story_5072_50721001_19_dialog_content = "Tô pronto, Arrie!",
  ui_story_5072_50721001_20_dialog_content = "As sombras escuras não podem interferir aqui.",
  ui_story_5072_50721001_21_dialog_content = "Podemos surpreendê-lo e vencer decisivamente.",
  ui_story_5072_50721001_22_dialog_content = "Entendi. Estou contando com você, Espada Mágica...",
  ui_story_5072_50721001_23_dialog_content = "Pato!",
  ui_story_5072_50721001_24_dialog_content = "Vuuush—!",
  ui_story_5072_50721001_25_dialog_content = "O que... Ugh!",
  ui_story_5072_50721001_26_dialog_content = "Tum!",
  ui_story_5072_50721001_27_dialog_content = "O que aconteceu... Acabou?",
  ui_story_5072_50721001_28_dialog_content = "O Anfitrião de Vilanor, que tem uma recompensa por sua cabeça em todos os lugares, caiu assim?",
  ui_story_5072_50721001_29_dialog_content = "Não pode ser tão simples. Isso provavelmente foi armado para aumentar o preço da espada!",
  ui_story_5072_50721001_30_dialog_content = "Verdade, eu não acredito que uma espada possa ser má, ou tornar quem a empunha perverso.",
  ui_story_5072_50721001_31_dialog_content = "É apenas uma espada arcano estrangeira. Veja, não há nada de maligno nela...",
  ui_story_5072_50721001_32_dialog_content = "Não, coloque-o para baixo!",
  ui_story_5072_50721001_33_dialog_content = "Argh! Vingança... Vingança!",
  ui_story_5072_50721001_34_dialog_content = "Ele está possuído.",
  ui_story_5072_50721001_35_dialog_content = "Droga!",
  ui_story_5072_50721001_36_dialog_content = "De fato, a espada é o problema! Há uma maldição nela!",
  ui_story_5072_50721001_37_dialog_content = "Quem quer que o possua se torna o Anfitrião de Vilanor!",
  ui_story_5072_50721001_38_dialog_content = "E está ficando mais forte quanto mais pessoas ele possui.",
  ui_story_5072_50721001_39_dialog_content = "O que você está olhando... espadachim!",
  ui_story_5072_50721001_40_dialog_content = "Cuidado, chamamos a atenção dele!",
  ui_story_5072_50721001_41_dialog_content = "Clang!",
  ui_story_5072_50721001_42_dialog_content = "Hum...",
  ui_story_5072_50721001_43_dialog_content = "Está batendo mais forte agora.",
  ui_story_5072_50721001_44_dialog_content = "É como se eu e minha espada de alguma forma o tivéssemos animado...",
  ui_story_5072_50721001_45_dialog_content = "Clang!",
  ui_story_5072_50721001_46_dialog_content = "Como espadachim... você é patético.",
  ui_story_5072_50721001_47_dialog_content = "Então, como eu, você não é um espadachim...",
  ui_story_5072_50721001_48_dialog_content = "Ignore isso e vamos tentar de novo!",
  ui_story_5072_50721001_49_dialog_content = "Argh...!",
  ui_story_5072_50721001_50_dialog_content = "Swoosh— Clang—!",
  ui_story_5072_50721001_51_dialog_content = "Você não pode me machucar assim.",
  ui_story_5072_50721001_52_dialog_content = "Você pode ter sua própria consciência, mas na verdade você também é apenas um substituto...",
  ui_story_5072_50721001_53_dialog_content = "Um controlado por uma espada, incapaz de liberar seu verdadeiro poder.",
  ui_story_5072_50721001_54_dialog_content = "A razão pela qual eu não posso te derrotar agora é porque...",
  ui_story_5072_50721001_55_dialog_content = "(Está muito lotado aqui para eu balançar minha espada livremente...)",
  ui_story_5072_50721001_56_dialog_content = "(Mas eu tenho que esconder esse fato ou vai ser pior quando ele fizer um refém...)",
  ui_story_5072_50721001_57_dialog_content = "(O que fazer...)",
  ui_story_5072_50721001_58_dialog_content = "Você sabe nadar, Arrie?",
  ui_story_5072_50721001_59_dialog_content = "O quê? Sim, um pouco... Você tem uma ideia, Espada Mágica?",
  ui_story_5072_50721001_60_dialog_content = "Eu já tracei a rota. Você leva o Anfitrião de Vilanor no bote com você.",
  ui_story_5072_50721001_61_dialog_content = "Então derrube-o na água!",
  ui_story_5072_50721001_62_dialog_content = "Mas se você não é um nadador forte, este é um plano muito arriscado...",
  ui_story_5072_50721001_63_dialog_content = "Obrigado, mas ainda vou tentar, já que essa é a melhor opção que temos.",
  ui_story_5072_50721001_64_dialog_content = "Vou te mostrar o verdadeiro poder da minha Espada Mágica!",
  ui_story_5072_50721001_65_dialog_content = "Venha, substituto... Você é apenas um seixo no meu caminho de vingança!",
  ui_story_5072_50721002_1_dialog_content = "Golpe de Espinho!",
  ui_story_5072_50721002_2_dialog_content = "Urgh...!",
  ui_story_5072_50721002_3_dialog_content = "Que inesperado.",
  ui_story_5072_50721002_4_dialog_content = "É porque eu não estou totalmente aclimatado a este novo corpo?",
  ui_story_5072_50721002_5_dialog_content = "Desista.",
  ui_story_5072_50721002_6_dialog_content = "Ou meu próximo golpe te enviará para o Rio Dourado!",
  ui_story_5072_50721002_7_dialog_content = "Você não vai possuir ninguém uma vez que você tenha afundado até o fundo.",
  ui_story_5072_50721002_8_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5072_50721002_9_dialog_content = "Ai! Argh...",
  ui_story_5072_50721002_10_dialog_content = "Não vai desistir?",
  ui_story_5072_50721002_11_dialog_content = "(Estou ficando... cansado...)",
  ui_story_5072_50721002_12_dialog_content = "Qual é o problema? Onde está o golpe final que você prometeu?",
  ui_story_5072_50721002_13_dialog_content = "Você aguenta, Arrie?",
  ui_story_5072_50721002_14_dialog_content = "Eu vou te cobrir, então vá buscá-lo!",
  ui_story_5072_50721002_15_dialog_content = "Ai...!",
  ui_story_5072_50721002_16_dialog_content = "(Quanto mais essa luta se prolonga, mais aterrorizante se torna o poder do Vilanor...)",
  ui_story_5072_50721002_17_dialog_content = "(Eu não teria resistido sem a ajuda ativa da Espada Mágica...)",
  ui_story_5072_50721002_18_dialog_content = "(Esta não é uma batalha entre o Exército de Vilanor e eu, mas entre as duas espadas.)",
  ui_story_5072_50721002_19_dialog_content = "Não, eu não posso ser um fardo para a Espada Mágica.",
  ui_story_5072_50721002_20_dialog_content = "Você está bem, Arrie?",
  ui_story_5072_50721002_21_dialog_content = "Olha, não é o Anfitrião de Vilanor?",
  ui_story_5072_50721002_22_dialog_content = "O quê?!",
  ui_story_5072_50721002_23_dialog_content = "O bote derivou perto da costa?",
  ui_story_5072_50721002_24_dialog_content = "O número de espectadores também está aumentando. Isso não é bom...",
  ui_story_5072_50721002_25_dialog_content = "Não, há dois espadachins lutando!",
  ui_story_5072_50721002_26_dialog_content = "O que está na sombra é o Anfitrião de Vilanor, o outro é...",
  ui_story_5072_50721002_27_dialog_content = "A famosa mercenária de Umbraton com espinhos por todo o corpo, a Espada Mágica Arrie!",
  ui_story_5072_50721002_28_dialog_content = "Oh não, minha roupa... Meu disfarce foi descoberto.",
  ui_story_5072_50721002_29_dialog_content = "Sim, o barco vai atracar em breve, me dando muitos novos corpos para possuir!",
  ui_story_5072_50721002_30_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5072_50721002_31_dialog_content = "Obrigado por me poupar...",
  ui_story_5072_50721002_32_dialog_content = "Espere... estou exausto...",
  ui_story_5072_50721002_33_dialog_content = "O Anfitrião de Vilanor escapou de novo... Eu sinto muito...",
  ui_story_5072_50721101_1_dialog_content = "...",
  ui_story_5072_50721101_2_dialog_content = "...",
  ui_story_5072_50721101_3_dialog_content = "Ninguém deve me ver por aqui.",
  ui_story_5072_50721101_4_dialog_content = "Ufa, não preciso lutar por um tempo, pelo menos...",
  ui_story_5072_50721101_5_dialog_content = "Nossa, a Espada Mágica parece tão pesada de repente.",
  ui_story_5072_50721101_6_dialog_content = "O que você está fazendo aqui, Arrie? Eu estive procurando por você.",
  ui_story_5072_50721101_7_dialog_content = "Ah, oi...",
  ui_story_5072_50721101_8_dialog_content = "Perdoe-me por não ter ido até você.",
  ui_story_5072_50721101_9_dialog_content = "Bem, tenho boas notícias para compartilhar.",
  ui_story_5072_50721101_10_dialog_content = "O quartel-general concordou em nos ajudar a trazer o Exército de Vilanor e guardar a espada.",
  ui_story_5072_50721101_11_dialog_content = "Então temos um novo objetivo e nosso objetivo principal agora é...",
  ui_story_5072_50721101_12_dialog_content = "Hum, desculpe...",
  ui_story_5072_50721101_13_dialog_content = "Desculpe? Qual o problema, Arrie?",
  ui_story_5072_50721101_14_dialog_content = "Eu não acho que posso continuar o trabalho.",
  ui_story_5072_50721101_15_dialog_content = "...",
  ui_story_5072_50721101_16_dialog_content = "Eu deveria estar me desculpando por continuar divagando sozinho.",
  ui_story_5072_50721101_17_dialog_content = "Ouvi pessoas falando sobre dois espadachins lutando no rio. Vendo como você está agora...",
  ui_story_5072_50721101_18_dialog_content = "Algo deu errado quando você lutou contra o Exército de Vilanor?",
  ui_story_5072_50721101_19_dialog_content = "Não me diga que alguns desses marinheiros cabeça-dura confundiram você com o Anfitrião de Vilanor?!",
  ui_story_5072_50721101_20_dialog_content = "Estou bem mesmo que seja esse o caso e receba olhares de lado. Eu estou acostumado com isso.",
  ui_story_5072_50721101_21_dialog_content = "Quero desistir porque agora percebo completamente...",
  ui_story_5072_50721101_22_dialog_content = "Eu não consigo derrotar o Anfitrião de Vilanor.",
  ui_story_5072_50721101_23_dialog_content = "Como um substituto, simplesmente não consigo vencê-lo.",
  ui_story_5072_50721101_24_dialog_content = "Procuração? Esse é um direito reservado apenas para artesãos. Não brigue comigo por isso, Arrie.",
  ui_story_5072_50721101_25_dialog_content = "O Anfitrião de Vilanor colocou ideias loucas na sua cabeça? Não dê ouvidos a isso!",
  ui_story_5072_50721101_26_dialog_content = "Não, ele estava certo...",
  ui_story_5072_50721101_27_dialog_content = "Como ele, não sou um espadachim, mas um substituto, então não consigo liberar todo o poder da minha espada.",
  ui_story_5072_50721101_28_dialog_content = "Enquanto o Exército de Vilanor tem acesso total à sua lâmina, estou segurando a Espada Mágica.",
  ui_story_5072_50721101_29_dialog_content = "Isso é um absurdo, Arrie.",
  ui_story_5072_50721101_30_dialog_content = "A sua é o oposto polar daquela espada sinistra e vingativa. Ela te protege.",
  ui_story_5072_50721101_31_dialog_content = "Sua espada ficaria triste ao ouvir você dizer isso.",
  ui_story_5072_50721101_32_dialog_content = "Não, minha intenção não é depreciar a Espada Mágica.",
  ui_story_5072_50721101_33_dialog_content = "Cuidou muito bem de mim e nunca me chamou de substituto.",
  ui_story_5072_50721101_34_dialog_content = "Mas sempre fui eu quem é o dependente.",
  ui_story_5072_50721101_35_dialog_content = "A espada pode estar sem mim, mas eu não posso estar sem ela.",
  ui_story_5072_50721101_36_dialog_content = "É um testemunho do poder da Espada Mágica que eu até sobrevivi para ser um mercenário.",
  ui_story_5072_50721101_37_dialog_content = "Tire isso e eu sou apenas uma garota fraca e sem graça que não é boa em nada.",
  ui_story_5072_50721101_38_dialog_content = "Vamos lá, Arrie. Isso não é quem você é para mim. Você é um mercenário confiável e poderoso por direito próprio!",
  ui_story_5072_50721101_39_dialog_content = "Mas se eu não tiver a espada, não terei nenhum valor para você.",
  ui_story_5072_50721101_40_dialog_content = "Assim como agora, ninguém vai me ver como uma socialite depois de rasgar a roupa que você me deu.",
  ui_story_5072_50721101_41_dialog_content = "Sou apenas Arrie, uma mercenária de Umbraton com espinhos por todo o corpo.",
  ui_story_5072_50721101_42_dialog_content = "Talvez com um portador maior, ele derrotará facilmente o Vilanor.",
  ui_story_5072_50721101_43_dialog_content = "Ninguém possuído pelo Vilanor é mais resistente do que você, Arrie.",
  ui_story_5072_50721101_44_dialog_content = "Pode mudar de portador à vontade, por isso tem uma vantagem decisiva em vigor.",
  ui_story_5072_50721101_45_dialog_content = "Mas eu não posso vencê-lo. Eu até rasguei o disfarce vital para a missão. Esses são os fatos.",
  ui_story_5072_50721101_46_dialog_content = "Talvez você devesse contratar um mercenário melhor para terminar o trabalho.",
  ui_story_5072_50721101_47_dialog_content = "Arrie...",
  ui_story_5072_50721101_48_dialog_content = "...",
  ui_story_5072_50721101_49_dialog_content = "Onde você está indo, Arrie?",
  ui_story_5072_50721101_50_dialog_content = "Não sei mesmo.",
  ui_story_5072_50721101_51_dialog_content = "Você está desistindo do emprego? E de você mesmo também?",
  ui_story_5072_50721101_52_dialog_content = "Eu simplesmente não consigo fazer isso...",
  ui_story_5072_50721101_53_dialog_content = "...",
  ui_story_5072_50721101_54_dialog_content = "Vou deixar a decisão final para você...",
  ui_story_5072_50721101_55_dialog_content = "Mas antes de desistir, se importa se eu te contar uma história?",
  ui_story_5072_50721101_56_dialog_content = "História?",
  ui_story_5072_50721101_57_dialog_content = "Sim, uma que acabei de ouvir... não, apenas lembrei, sobre um herói amaldiçoado pelos Eclipsitas.",
  ui_story_5072_50721101_58_dialog_content = "Um antigo herói foi amaldiçoado com uma doença eterna em sua batalha contra os Eclipsitas.",
  ui_story_5072_50721101_59_dialog_content = "Não apenas isso, qualquer descendente dele que seja proficiente em caçar Eclipsitas também morrerá jovem por causa da maldição.",
  ui_story_5072_50721101_60_dialog_content = "Qualquer pessoa normal abandonaria tal destino heroico por medo.",
  ui_story_5072_50721101_61_dialog_content = "E lembre a família dele para se afastar do treinamento ou qualquer guerra contra os Eclipsitas.",
  ui_story_5072_50721101_62_dialog_content = "Mas o herói escolheu usar seu corpo amaldiçoado como o componente base.",
  ui_story_5072_50721101_63_dialog_content = "E forje uma espada sob a bênção da lua.",
  ui_story_5072_50721101_64_dialog_content = "A partir de então, a espada protegeu seus descendentes habilidosos em combate e contra a maldição dos Eclipsitas.",
  ui_story_5072_50721101_65_dialog_content = "Todos eles lutaram bravamente...",
  ui_story_5072_50721102_1_dialog_content = "É isso para a história.",
  ui_story_5072_50721102_2_dialog_content = "Mas o confronto entre os herdeiros do herói e os Eclipsitas nunca terminará.",
  ui_story_5072_50721102_3_dialog_content = "Quanto maior o guerreiro, maior a proteção que a espada deve fornecer. Esse é o propósito da espada.",
  ui_story_5072_50721102_4_dialog_content = "Para mim, você está longe de ser insignificante, Arrie. Eu... a Espada Mágica irá proteger você...",
  ui_story_5072_50721102_5_dialog_content = "Porque eu reconheço quão notável você é.",
  ui_story_5072_50721102_6_dialog_content = "Estou muito grato por isso e sempre estive.",
  ui_story_5072_50721102_7_dialog_content = "Mas eu sou digno disso?",
  ui_story_5072_50721102_8_dialog_content = "Claro que você é. Eu sei que sou apenas uma espada.",
  ui_story_5072_50721102_9_dialog_content = "Apesar de uma história antiga e de desenvolver uma consciência, é basicamente isso que eu sou.",
  ui_story_5072_50721102_10_dialog_content = "Você decidiu meu destino e quem eu atingi. Você aprendeu a controlar meu poder.",
  ui_story_5072_50721102_11_dialog_content = "Seu espírito nunca diminuiu por causa dos efeitos colaterais que eu causei em você.",
  ui_story_5072_50721102_12_dialog_content = "Pelo contrário, foi você quem tem me influenciado, apontando os espinhos na direção certa.",
  ui_story_5072_50721102_13_dialog_content = "Isso é totalmente diferente do Vilanor sempre se aproveitando dos outros.",
  ui_story_5072_50721102_14_dialog_content = "Bem, como portadores, todos nós somos protegidos pelo grande poder de nossas respectivas lâminas...",
  ui_story_5072_50721102_15_dialog_content = "Você está errado, Arrie.",
  ui_story_5072_50721102_16_dialog_content = "Você realmente acha que o Vilanor estava protegendo seu portador?",
  ui_story_5072_50721102_17_dialog_content = "Hã?",
  ui_story_5072_50721102_18_dialog_content = "Parecia proteger o portador apenas porque não queria perder. Não se importava com quem o estava segurando.",
  ui_story_5072_50721102_19_dialog_content = "Essa é a natureza do Vilanor. Ele aceitará qualquer um.",
  ui_story_5072_50721102_20_dialog_content = "Mas você, Arrie, é o único e verdadeiro mestre de mim e da Espada Mágica!",
  ui_story_5072_50721102_21_dialog_content = "...",
  ui_story_5072_50721102_22_dialog_content = "Eu sou o mestre da Espada Mágica...",
  ui_story_5072_50721102_23_dialog_content = "Espere, isso significa que a história que você acabou de contar é a origem da minha espada?!",
  ui_story_5072_50721102_24_dialog_content = "Você descobriu... Como eu te disse antes, eu só sei sobre essa lâmina em particular.",
  ui_story_5072_50721102_25_dialog_content = "Esta espada é extremamente antiga, então eu só pude juntar sua memória através de fragmentos.",
  ui_story_5072_50721102_26_dialog_content = "Os detalhes podem não estar necessariamente corretos, então não me culpe.",
  ui_story_5072_50721102_27_dialog_content = "Não.",
  ui_story_5072_50721102_28_dialog_content = "Isso é o máximo que já aprendi sobre a maldição.",
  ui_story_5072_50721102_29_dialog_content = "Obrigado.",
  ui_story_5072_50721102_30_dialog_content = "Acho que sei o que devo fazer.",
  ui_story_5072_50721102_31_dialog_content = "Vou ver a Senhorita Armilla e terminar o trabalho!",
  ui_story_5072_50721102_32_dialog_content = "Senhorita Armilla...",
  ui_story_5072_50721102_33_dialog_content = "Arrie? Venha sentar comigo. Garçom, me dê mais duas cestas de pãezinhos de sopa com chili extra.",
  ui_story_5072_50721102_34_dialog_content = "Tá saindo!",
  ui_story_5072_50721102_35_dialog_content = "Uh, você está encontrando um informante aqui?",
  ui_story_5072_50721102_36_dialog_content = "Não. O prato e os utensílios são para você.",
  ui_story_5072_50721102_37_dialog_content = "O quê?",
  ui_story_5072_50721102_38_dialog_content = "Você estava apenas exausto naquela época, afinal. Eu tinha certeza que aquela sua Espada Mágica iria clarear sua cabeça.",
  ui_story_5072_50721102_39_dialog_content = "Você sabe sobre a minha espada mágica?",
  ui_story_5072_50721102_40_dialog_content = "Não realmente, mas eu sei como vocês dois lutam.",
  ui_story_5072_50721102_41_dialog_content = "A química que você tem não é algo que o Anfitrião de Vilanor poderia tocar.",
  ui_story_5072_50721102_42_dialog_content = "Desculpe por não ter pensado no que você disse antes.",
  ui_story_5072_50721102_43_dialog_content = "Não é só comigo, no entanto.",
  ui_story_5072_50721102_44_dialog_content = "Todas as pessoas inocentes na galeria que você salvou agradecem muito a você.",
  ui_story_5072_50721102_45_dialog_content = "Todos estão ansiosos para ver a heroína derrotar o maléfico Exército de Vilanor com sua espada mágica.",
  ui_story_5072_50721102_46_dialog_content = "Bem, se não for muito tarde, ainda posso terminar o trabalho?",
  ui_story_5072_50721102_47_dialog_content = "Não venho dizendo desde o início que o trabalho é seu e somente seu?",
  ui_story_5072_50721102_48_dialog_content = "Vamos comer enquanto a comida está quente... De qualquer forma, alguma ideia de como derrotar o Exército de Vilanor?",
  ui_story_5072_50721102_49_dialog_content = "Na verdade, eu tive a chance de derrotar o Vilanor com a ajuda da Espada Mágica.",
  ui_story_5072_50721102_50_dialog_content = "Ah?",
  ui_story_5072_50721102_51_dialog_content = "Estávamos em um bote e eu imaginei que se conseguisse jogá-lo na água, ele não seria capaz de possuir ninguém novamente.",
  ui_story_5072_50721102_52_dialog_content = "Mas eu estava muito cansado e tímido na época, então não consegui dar o golpe final.",
  ui_story_5072_50721102_53_dialog_content = "Se não houver mais ninguém por perto e, em vez de enfrentar diretamente o Anfitrião de Vilanor, eu o desarmar da espada...",
  ui_story_5072_50721102_54_dialog_content = "Talvez essa seja a maneira de subjugar isso.",
  ui_story_5072_50721102_55_dialog_content = "Essa é a Espada Mágica Arrie que eu conheço. Só você poderia pensar nesse plano.",
  ui_story_5072_50721102_56_dialog_content = "Mas o Vilanor provavelmente está antecipando isso agora, então pode não funcionar...",
  ui_story_5072_50721102_57_dialog_content = "Está bem. Vamos encontrar outra maneira de alcançar esse fim.",
  ui_story_5072_50721102_58_dialog_content = "Afinal, ele acabou de ganhar consciência não faz muito tempo.",
  ui_story_5072_50721102_59_dialog_content = "Ainda tem muito a aprender quando se trata de truques e estratégias.",
  ui_story_5072_50721102_60_dialog_content = "Faça uma pausa por agora, Arrie, e vá se trocar enquanto eu preparo as coisas.",
  ui_story_5072_50721102_61_dialog_content = "Vamos lançar o golpe final no Vilanor esta noite!",
  ui_story_5072_50721201_1_dialog_content = "Desculpe, Arrie, por chegar aqui tarde.",
  ui_story_5072_50721201_2_dialog_content = "Demorou mais do que eu pensava para informar aos caras enviados pela sede sobre o meu plano.",
  ui_story_5072_50721201_3_dialog_content = "Mas tudo está pronto para ir agora. Você está pronto para o confronto final com o Exército de Vilanor?",
  ui_story_5072_50721201_4_dialog_content = "Estou pronto. Mas para onde estou indo?",
  ui_story_5072_50721201_5_dialog_content = "A muralha.",
  ui_story_5072_50721201_6_dialog_content = "A muralha... Entendo.",
  ui_story_5072_50721201_7_dialog_content = "Derrube-o da muralha e não haverá ninguém por perto para ele possuir.",
  ui_story_5072_50721201_8_dialog_content = "Esse é o plano. Mas não será fácil atrair o Espadachim para lá.",
  ui_story_5072_50721201_9_dialog_content = "Avistamos o Anfitrião de Vilanor, Senhorita Armilla.",
  ui_story_5072_50721201_10_dialog_content = "Está bem. Precisamos nos apressar.",
  ui_story_5072_50721201_11_dialog_content = "...",
  ui_story_5072_50721201_12_dialog_content = "Ah, eu vejo muita gente.",
  ui_story_5072_50721201_13_dialog_content = "Mas você acha que isso é tudo o que é preciso para me subjugar?",
  ui_story_5072_50721201_14_dialog_content = "Você está lutando comigo!",
  ui_story_5072_50721201_15_dialog_content = "Ei, você não é o procurador?",
  ui_story_5072_50721201_16_dialog_content = "Acertei um ponto sensível? É por isso que você continua me perseguindo?",
  ui_story_5072_50721201_17_dialog_content = "Então eu vou provar o quão inferior você é para mim!",
  ui_story_5072_50721201_18_dialog_content = "<color=#e8d9bb>Clam! Clam!</color>",
  ui_story_5072_50721201_19_dialog_content = "Você continua fraco como sempre. Você não pode defender meus golpes sem sua espada mágica.",
  ui_story_5072_50721201_20_dialog_content = "Estou em uma terrível vantagem...",
  ui_story_5072_50721201_21_dialog_content = "Continue recuando. Quero ver até onde você consegue recuar.",
  ui_story_5072_50721201_22_dialog_content = "É um beco sem saída. Você já considerou a péssima situação em que se encontra agora?",
  ui_story_5072_50721201_23_dialog_content = "Você realmente achou que era um beco sem saída? Isso é mais fácil do que eu pensava, Hospedeiro de Vilanor... Não, eu deveria te chamar de Vilanor.",
  ui_story_5072_50721201_24_dialog_content = "Apresse-se, a Senhorita Arrie atraiu o Anfitrião de Vilanor para lá. Feche todas as saídas agora!",
  ui_story_5072_50721201_25_dialog_content = "<color=#e8d9bb>Clang... Wham!</color>",
  ui_story_5072_50721201_26_dialog_content = "O quê...?!",
  ui_story_5072_50721201_27_dialog_content = "É aqui que o seu reinado de terror termina.",
  ui_story_5072_50721201_28_dialog_content = "Não vou lutar contra você aqui. Você não pode me prender aqui! Amaldiçoo todos eles!",
  ui_story_5072_50721201_29_dialog_content = "Não se preocupe com eles. Eu te disse, você está lutando comigo!",
  ui_story_5072_50721301_1_dialog_content = "Tudo bem, acho que nenhum de nós pode ir a lugar nenhum.",
  ui_story_5072_50721301_2_dialog_content = "Então você acha que este é o meu fim? Para mim, parece mais o seu último lugar de descanso!",
  ui_story_5072_50721301_3_dialog_content = "Toma essa!",
  ui_story_5072_50721301_4_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721301_5_dialog_content = "Não pousou?!",
  ui_story_5072_50721301_6_dialog_content = "Você acha que tem espaço para correr neste lugar apertado?",
  ui_story_5072_50721301_7_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721301_8_dialog_content = "...",
  ui_story_5072_50721301_9_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5072_50721301_10_dialog_content = "Parou!",
  ui_story_5072_50721301_11_dialog_content = "Impossível! Você é apenas um substituto, como pode trabalhar tão bem com a Espada Mágica!",
  ui_story_5072_50721301_12_dialog_content = "Proxy? Não, essa espada e eu somos parceiros!",
  ui_story_5072_50721301_13_dialog_content = "Eu o guio para atacar, e ele me guia para o meu destino!",
  ui_story_5072_50721301_14_dialog_content = "<color=#e8d9bb>Vuuush... Clang!</color>",
  ui_story_5072_50721301_15_dialog_content = "Como é possível para você bloquear isso?!",
  ui_story_5072_50721301_16_dialog_content = "Minha vez!",
  ui_story_5072_50721301_17_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721301_18_dialog_content = "Essa não!",
  ui_story_5072_50721301_19_dialog_content = "Então, esse é o seu plano, entendi.",
  ui_story_5072_50721301_20_dialog_content = "Derrube-me do parapeito e não haverá ninguém para eu possuir.",
  ui_story_5072_50721301_21_dialog_content = "...",
  ui_story_5072_50721301_22_dialog_content = "Hehe... Hahaha!",
  ui_story_5072_50721301_23_dialog_content = "Qual a graça?",
  ui_story_5072_50721301_24_dialog_content = "Você ignorou um detalhe importante.",
  ui_story_5072_50721301_25_dialog_content = "Eu tenho um fantoche perfeitamente dispensável!",
  ui_story_5072_50721301_26_dialog_content = "Como você vai lutar se eu apenas usá-lo puramente como um escudo humano? Você vai matar um homem inocente com sua espada?",
  ui_story_5072_50721301_27_dialog_content = "Hmm, a Senhorita Armilla realmente é um gênio por prever isso.",
  ui_story_5072_50721301_28_dialog_content = "Ah bem. Aqui vem o anzol!",
  ui_story_5072_50721301_29_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5072_50721301_30_dialog_content = "O que é isto?!",
  ui_story_5072_50721301_31_dialog_content = "Gancho de pintle e corrente, para que você não possa mais explorar o corpo do mortal amarrado.",
  ui_story_5072_50721301_32_dialog_content = "Não... Me solte, agora!",
  ui_story_5072_50721301_33_dialog_content = "Pare de se contorcer. O melhor artesão de Longzhou fez isso. Quanto mais você luta, mais apertado fica.",
  ui_story_5072_50721301_34_dialog_content = "A Espada Mágica nasceu sob a bênção da lua.",
  ui_story_5072_50721301_35_dialog_content = "Por favor, abençoe novamente para que eu possa subjugar este Vilanor!",
  ui_story_5072_50721302_1_dialog_content = "Este é o fim!",
  ui_story_5072_50721302_2_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721302_3_dialog_content = "Aaaaaaargh!!",
  ui_story_5072_50721302_4_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5072_50721302_5_dialog_content = "A senhora de Longzhou venceu!",
  ui_story_5072_50721302_6_dialog_content = "Rapidamente, suba e liberte a vítima da espada amaldiçoada!",
  ui_story_5072_50721302_7_dialog_content = "Parabéns, minha senhora. Missão cumprida.",
  ui_story_5072_50721302_8_dialog_content = "Nesse caso, eu não sou mais a senhora de Longzhou.",
  ui_story_5072_50721302_9_dialog_content = "O que você está dizendo? Que identidade e imagem são indeléveis na mente de todos agora.",
  ui_story_5072_50721302_10_dialog_content = "Tornou-se uma parte de você, assim como a Espada Mágica Arrie.",
  ui_story_5072_50721302_11_dialog_content = "Como está o cara que foi possuído?",
  ui_story_5072_50721302_12_dialog_content = "Ele está bem. Você evitou os pontos vitais em todos os seus ataques. Muito gentil da sua parte.",
  ui_story_5072_50721302_13_dialog_content = "O maior problema agora é...",
  ui_story_5072_50721302_14_dialog_content = "Eu vou cuidar disso. Com a luva que você me deu, Senhorita Armilla, não deveria ser um problema.",
  ui_story_5072_50721302_15_dialog_content = "Mas a luva não vai suprimir todos os seus poderes, então assim que você sentir que algo está errado, solte imediatamente, ok?",
  ui_story_5072_50721302_16_dialog_content = "Sim. Vou manter isso em mente...",
  ui_story_5072_50721302_17_dialog_content = "...",
  ui_story_5072_50721302_18_dialog_content = "(Ódio, ódio, ódio...)",
  ui_story_5072_50721302_19_dialog_content = "(Mate, mate, mate...)",
  ui_story_5072_50721302_20_dialog_content = "<size=45>(Eu busco... vingança...!)</size>",
  ui_story_5072_50721302_21_dialog_content = "Ei, você está bem, Arrie?!",
  ui_story_5072_50721302_22_dialog_content = "Hum...",
  ui_story_5072_50721302_23_dialog_content = "Não, temos que tirar a espada amaldiçoada antes que ela tome conta de Arrie!",
  ui_story_5072_50721302_24_dialog_content = "...",
  ui_story_5072_50721302_25_dialog_content = "Afe!",
  ui_story_5072_50721302_26_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721302_27_dialog_content = "O Vilanor... Está voando por conta própria!",
  ui_story_5072_50721302_28_dialog_content = "...",
  ui_story_5072_50721302_29_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721302_30_dialog_content = "Barreira Bell, ataque!",
  ui_story_5072_50721302_31_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5072_50721302_32_dialog_content = "Isso deve resolver.",
  ui_story_5072_50721302_33_dialog_content = "Tudo bem, Arrie?",
  ui_story_5072_50721401_1_dialog_content = "Fale comigo, Arrie!",
  ui_story_5072_50721401_2_dialog_content = "Estou bem. No entanto...",
  ui_story_5072_50721401_3_dialog_content = "A espada escapou mais uma vez por causa de mim.",
  ui_story_5072_50721401_4_dialog_content = "Se possuir outra pessoa...",
  ui_story_5072_50721401_5_dialog_content = "Temos que começar do começo novamente.",
  ui_story_5072_50721401_6_dialog_content = "Tudo bem, temos tempo.",
  ui_story_5072_50721401_7_dialog_content = "O toque de recolher da Guilda Umbraton está em vigor agora, então não há ninguém na rua para ser o fantoche de Vilanor.",
  ui_story_5072_50721401_8_dialog_content = "Além disso, no estado atual, provavelmente saiu por instinto e não tem desejo de possuir ninguém.",
  ui_story_5072_50721401_9_dialog_content = "Então, temos que nos mover agora e rastreá-lo.",
  ui_story_5072_50721401_10_dialog_content = "Mas Twin Pavilions Bay é enorme... Por onde começamos?",
  ui_story_5072_50721401_11_dialog_content = "Se não conseguirmos encontrar antes do amanhecer...",
  ui_story_5072_50721401_12_dialog_content = "Relaxe, eu marquei.",
  ui_story_5072_50721401_13_dialog_content = "Marcou?",
  ui_story_5072_50721401_14_dialog_content = "Sim, mas isso.",
  ui_story_5072_50721401_15_dialog_content = "<color=#e8d9bb>Ding, ding...</color>",
  ui_story_5072_50721401_16_dialog_content = "Sino?",
  ui_story_5072_50721401_17_dialog_content = "Sim. Eu amarrei um nele antes que ele voasse.",
  ui_story_5072_50721401_18_dialog_content = "Está tudo quieto na cidade agora, então podemos seguir os guizos até a espada.",
  ui_story_5072_50721401_19_dialog_content = "Eu vejo. Vamos indo então!",
  ui_story_5072_50721401_20_dialog_content = "É urgente. Devemos nos dividir?",
  ui_story_5072_50721401_21_dialog_content = "Não, é um grande problema se ele possuir um de nós.",
  ui_story_5072_50721401_22_dialog_content = "Juntos, podemos cuidar um do outro, mesmo quando sobrecarregados pelo ódio da espada.",
  ui_story_5072_50721401_23_dialog_content = "Entendo. Ah, desculpe por subestimar a emoção crua que isso projetou. Não esperava que fosse tão intenso.",
  ui_story_5072_50721401_24_dialog_content = "Não é sua culpa, Arrie. Eu fui um pouco descuidado também.",
  ui_story_5072_50721401_25_dialog_content = "Seu rosto estava em agonia quando você segurou a espada. O que você sentiu?",
  ui_story_5072_50721401_26_dialog_content = "Desprezo avassalador, dor, pânico...",
  ui_story_5072_50721401_27_dialog_content = "Parecia detestar tanto o mundo quanto seus próprios sofrimentos ao extremo.",
  ui_story_5072_50721401_28_dialog_content = "É por isso que continuou possuindo pessoas e buscando vingança, como se quisesse acabar com o ódio sem limites...",
  ui_story_5072_50721401_29_dialog_content = "A sede descobriu que o proprietário da galera é um comerciante do mercado negro que conseguiu a espada dos piratas.",
  ui_story_5072_50721401_30_dialog_content = "No entanto, o trauma de ser roubado de casa gerou maldade e perverteu os antigos poderes da espada.",
  ui_story_5072_50721401_31_dialog_content = "Até que ascendeu para se tornar uma espada maligna e amaldiçoou as antiguidades ao redor, bem como os marinheiros que as transportavam.",
  ui_story_5072_50721401_32_dialog_content = "A Guilda da Concha Vermelha, o colecionador e o espadachim todos se envolveram em seu caminho de vingança.",
  ui_story_5072_50721401_X32_dialog_content = "Se o negócio e a ganância não acabarem, o rancor provavelmente nunca acabará também.",
  ui_story_5072_50721401_33_dialog_content = "Então, o que fazemos agora não é trancá-lo?",
  ui_story_5072_50721401_34_dialog_content = "Não. Precisamos eliminar suas emoções negativas. A melhor maneira de fazer isso é...",
  ui_story_5072_50721401_35_dialog_content = "Traga de volta para casa.",
  ui_story_5072_50721401_36_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5072_50721401_37_dialog_content = "Claro como um sino... Vamos, por aqui!",
  ui_story_5072_50721601_1_dialog_content = "O som está vindo deste barco.",
  ui_story_5072_50721601_2_dialog_content = "Vamos entrar às cegas?",
  ui_story_5072_50721601_3_dialog_content = "Sim. Acho que sei onde será.",
  ui_story_5072_50721601_4_dialog_content = "Você notou que este navio parece diferente dos outros que vimos lá fora?",
  ui_story_5072_50721601_5_dialog_content = "Parece apenas outro navio no Rio Dourado, mas o convés é na verdade...",
  ui_story_5072_50721601_6_dialog_content = "Típico de um transatlântico Lin.",
  ui_story_5072_50721601_7_dialog_content = "O Vilanor lançou uma ilusão de um transatlântico sobre um cargueiro do Rio Dourado.",
  ui_story_5072_50721601_8_dialog_content = "Este é o tipo de navio que ele queria pegar e voltar para casa.",
  ui_story_5072_50721601_9_dialog_content = "Estamos no compartimento principal de carga.",
  ui_story_5072_50721601_10_dialog_content = "Ouvi dizer que o dono deste navio trabalha para piratas e criminosos, por isso ele precisava de um grande compartimento de carga...",
  ui_story_5072_50721601_11_dialog_content = "Eles também extorquiram dinheiro de proteção dos navios vizinhos.",
  ui_story_5072_50721601_12_dialog_content = "Isso explicaria. Todo esse lucro crescente e ganância amaldiçoaram a espada.",
  ui_story_5072_50721601_13_dialog_content = "Eu me pergunto quantas relíquias de Longzhou acabaram em Astra assim e nunca mais viram sua terra natal.",
  ui_story_5072_50721601_14_dialog_content = "Então, o Vilanor veio aqui na esperança de voltar para Longzhou neste navio...",
  ui_story_5072_50721601_15_dialog_content = "Correto. De volta ao seu lar e redescobrir seu propósito.",
  ui_story_5072_50721601_16_dialog_content = "Espada Mágica? Faz muito tempo que não ouço falar de você.",
  ui_story_5072_50721601_17_dialog_content = "O que mais você consegue sentir vindo do Vilanor?",
  ui_story_5072_50721601_18_dialog_content = "Devo dizer, foi completamente corrompido pela avareza para que eu pudesse pegar qualquer outra coisa.",
  ui_story_5072_50721601_19_dialog_content = "Mas o anseio por casa e a tentativa de encontrar seu propósito estão lá...",
  ui_story_5072_50721601_20_dialog_content = "Continuou esperando para voltar, apenas para ser deslocado e adquirido como um colecionável vez após vez, até se tornar uma máquina de matar...",
  ui_story_5072_50721601_21_dialog_content = "A agonia, a miséria, a resignação.",
  ui_story_5072_50721601_22_dialog_content = "Se eu passasse pelo mesmo sofrimento, talvez isso também me tornasse malvado.",
  ui_story_5072_50721601_23_dialog_content = "Parou!",
  ui_story_5072_50721601_24_dialog_content = "Claro que não, porque eu tenho o melhor dono do mundo!",
  ui_story_5072_50721601_25_dialog_content = "...!",
  ui_story_5072_50721601_26_dialog_content = "Cuidado, Arrie, acho que ele nos viu.",
  ui_story_5072_50721601_27_dialog_content = "E está nos vendo como inimigos.",
  ui_story_5072_50721601_28_dialog_content = "Alguma maneira de acalmá-lo?",
  ui_story_5072_50721601_29_dialog_content = "Mesmo que haja, ainda temos que subjugar eles primeiro. Vamos fazer isso, Arrie.",
  ui_story_5072_50721601_30_dialog_content = "Claro!",
  ui_story_5072_50721602_1_dialog_content = "Acabou?",
  ui_story_5072_50721602_2_dialog_content = "Não pode nos atacar tão cedo.",
  ui_story_5072_50721602_3_dialog_content = "Eu trouxe uma caixa para a espada comigo para que não precisemos tocá-la...",
  ui_story_5072_50721602_4_dialog_content = "Está tudo bem, eu tenho isso.",
  ui_story_5072_50721602_5_dialog_content = "Espere, você não está usando a mão nua, está...",
  ui_story_5072_50721602_6_dialog_content = "...",
  ui_story_5072_50721602_7_dialog_content = "...",
  ui_story_5072_50721602_8_dialog_content = "Huff... Puff...",
  ui_story_5072_50721602_9_dialog_content = "Está bem. Está bem...",
  ui_story_5072_50721602_10_dialog_content = "Estamos aqui para resgatar você.",
  ui_story_5072_50721602_11_dialog_content = "Estou satisfeito que você consiga ir para casa depois de uma jornada tão longa.",
  ui_story_5072_50721602_12_dialog_content = "É um milagre.",
  ui_story_5072_50721602_13_dialog_content = "O Vilanor está se acalmando.",
  ui_story_5072_50721602_14_dialog_content = "Acho que a mentalidade de quem empunha realmente pode afetar uma espada... Nem mesmo os gadgets conseguem fazer isso.",
  ui_story_5072_50721602_15_dialog_content = "Por favor, pegue esta espada.",
  ui_story_5072_50721602_16_dialog_content = "Certifique-se de que ele volte para onde pertence.",
  ui_story_5072_50721602_17_dialog_content = "Pode deixar.",
  ui_story_5072_50721602_18_dialog_content = "Ai...",
  ui_story_5072_50721602_19_dialog_content = "Ele não quer te deixar...",
  ui_story_5072_50721602_20_dialog_content = "Já que nunca teve um dono que se importasse genuinamente tanto quanto você.",
  ui_story_5072_50721602_21_dialog_content = "Obrigado pela oferta, mas não posso ser seu dono porque já tenho uma espada minha.",
  ui_story_5072_50721602_22_dialog_content = "Sem mencionar que você ainda tem um propósito a buscar?",
  ui_story_5072_50721602_23_dialog_content = "Espero que você encontre alguém que realmente valorize você em casa...",
  ui_story_5072_50721602_24_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5072_50721602_25_dialog_content = "Vamos chamar isso de adeus final.",
  ui_story_5072_50721602_26_dialog_content = "Vou providenciar um navio para levá-lo de volta a Longzhou o mais rápido possível.",
  ui_story_5072_50721602_27_dialog_content = "Como seu pagamento...",
  ui_story_5072_50721602_28_dialog_content = "Isso não é importante agora. Você deve prosseguir com seu plano para essa espada imediatamente.",
  ui_story_5072_50721602_29_dialog_content = "Estava em fragmentos, mas consegui uma boa imagem do passado da Espada Mágica.",
  ui_story_5072_50721602_30_dialog_content = "Opor-se às \"maldições\" não é um problema para mim agora, desde que eu tenha a lâmina comigo.",
  ui_story_5072_50721602_31_dialog_content = "Eu devo isso a você, senhorita Armilla.",
  ui_story_5072_50721602_32_dialog_content = "Mas eu não fiz nada. No entanto, sinta-se à vontade para me ver a qualquer momento para as últimas notícias sobre Longzhou.",
  ui_story_5072_50721602_33_dialog_content = "Veja-me de qualquer maneira, quando estiver procurando por gadgets ou roupas personalizadas de Longzhou também.",
  ui_story_5072_50721602_34_dialog_content = "Entendido.",
  ui_story_5072_50721602_35_dialog_content = "Até a próxima!",
  ui_story_5072_50721602_36_dialog_content = "Até a próxima.",
  ui_story_5072_50721602_37_dialog_content = "Você fez muito bem, Espada Mágica.",
  ui_story_5072_50721602_38_dialog_content = "Se essa espada tivesse um desejo, você também deve ter um, certo?",
  ui_story_5072_50721602_39_dialog_content = "Há algum lugar que você queira ir? Devo te levar de volta para onde meus pais te encontraram?",
  ui_story_5072_50721602_40_dialog_content = "Notei que você estava meio relutante quando entregou aquela espada.",
  ui_story_5072_50721602_41_dialog_content = "O pensamento de me substituir passou pela sua cabeça?",
  ui_story_5072_50721602_42_dialog_content = "O que? Não, nunca! Não era isso que eu estava pensando!",
  ui_story_5072_50721602_43_dialog_content = "Eu sei, eu sei... Só estou brincando com você, Arrie.",
  ui_story_5072_50721602_44_dialog_content = "Todo mundo nasceu em algum lugar e vai viajar para muitos lugares importantes na vida.",
  ui_story_5072_50721602_45_dialog_content = "Mas por enquanto, ficar com você é o desejo da espada... uh, meu único desejo.",
  ui_story_5072_50721602_46_dialog_content = "É verdade? Tem certeza?",
  ui_story_5072_50721602_47_dialog_content = "Claro. Como meu dono, espero que você tenha mais fé em si mesmo.",
  ui_story_5072_50721602_48_dialog_content = "É imutável que você foi escolhido pelo destino para sofrer as desgraças que tem...",
  ui_story_5072_50721602_49_dialog_content = "O fato de eu ter nascido para te proteger também é imutável.",
  ui_story_5072_50721602_50_dialog_content = "Eu ficarei miserável se não puder estar com você e compartilhar seus fardos.",
  ui_story_5072_50721602_51_dialog_content = "Por favor, deixe-me ficar para que eu não me torne malvado e cheio de rancor!",
  ui_story_5072_50721602_52_dialog_content = "Tudo bem, tudo bem. Deixe-me agradecer por toda a ajuda futura desde já então!",
  ui_story_5072_50721602_53_dialog_content = "Já é manhã.",
  ui_story_5072_50721602_54_dialog_content = "É um dia perfeito para uma senhora ir às compras... Espere, eu não sou mais uma socialite.",
  ui_story_5072_50721602_X54_dialog_content = "Como o Espadachim Mágico... ou apenas como eu mesmo.",
  ui_story_5072_50721602_55_dialog_content = "Eu tenho um futuro à minha frente... e a Espada Mágica também.",
  ui_story_5072_50721602_56_dialog_content = "Ei, hora de terminar sua história, vidente.",
  ui_story_5072_50721602_57_dialog_content = "Você não precisa dizer isso de novo.",
  ui_story_5072_50721602_58_dialog_content = "Mas onde está o sujeito irritado para quem eu fiz uma leitura? Eu não o vejo hoje.",
  ui_story_5072_50721602_59_dialog_content = "Bem, foi isso que aconteceu...",
  ui_story_5072_50721602_60_dialog_content = "O pequeno lucro que ele fez foi negociando antiguidades no mercado negro.",
  ui_story_5072_50721602_X60_dialog_content = "A sede está investigando isso agora e confiscou as remessas.",
  ui_story_5072_50721602_61_dialog_content = "Ele perdeu todo o seu dinheiro e provavelmente está tendo um ataque de raiva neste exato momento.",
  ui_story_5072_50721602_62_dialog_content = "Entendo. Parece que o homem está realmente sem sorte agora.",
  ui_story_5072_50721602_63_dialog_content = "O que vai, volta. Você precisa ter cuidado, mesmo quando está no seu auge.",
  ui_story_5072_50721602_64_dialog_content = "Ou você não terá para onde ir a não ser para baixo quando o jogo virar.",
  ui_story_5072_50721602_65_dialog_content = "Aproveite..!",
  ui_story_5072_50721602_66_dialog_content = "Na infelicidade dos outros...!",
  ui_story_5072_50721602_67_dialog_content = "Esqueça aquele infeliz e termine sua história!",
  ui_story_5072_50721602_68_dialog_content = "Claro. Retomando de onde paramos, o espadachim chegou à Twin Pavilions Bay.",
  ui_story_5072_50721602_69_dialog_content = "Em uma missão de um artesão estrangeiro para se livrar daquela espada amaldiçoada que controla a mente.",
  ui_story_5072_50721602_70_dialog_content = "O espadachim encontrou, lutou e encurralou a espada amaldiçoada.",
  ui_story_5072_50721602_X70_dialog_content = "Apenas para a espada amaldiçoada ressoar com sua própria espada mágica.",
  ui_story_5072_50721602_71_dialog_content = "Que quase enredou o espadachim sob seu feitiço.",
  ui_story_5072_50721602_72_dialog_content = "Felizmente, sua espada mágica interveio no momento crucial e mostrou a ela sua própria história para quebrar o controle.",
  ui_story_5072_50721602_X72_dialog_content = "O espadachim então desafiou a espada amaldiçoada para um duelo sob uma lua cheia.",
  ui_story_5072_50721602_X73_dialog_content = "Na luz da lua cheia, no topo da muralha de Twin Pavilions Bay, eles lutaram em uma batalha equilibrada...",
  ui_story_5072_50721602_73_dialog_content = "Vamos, nos diga quem ganhou!",
  ui_story_5072_50721602_74_dialog_content = "Você acha que estaríamos aproveitando tudo isso se a espada amaldiçoada vencesse?",
  ui_story_5072_50721602_75_dialog_content = "Bom...",
  ui_story_5072_50721602_76_dialog_content = "Como eles disseram...",
  ui_story_5072_50721602_77_dialog_content = "Trate uma espada como você trata uma pessoa e a espada retribuirá da mesma forma.",
  ui_story_5072_50721602_78_dialog_content = "Em sonhos, o impossível é possível. Espinhos podem florescer, espadas podem falar.",
  ui_story_5072_50721602_79_dialog_content = "A espada expressa o que está em sua mente, não esqueça o que você ouviu em seus sonhos!",
  ui_story_5072_50721602_80_dialog_content = "Tudo o que você faz é nos deixar em suspense. Vamos sair daqui!",
  ui_story_5072_50721602_81_dialog_content = "Também está na hora de eu ir.",
  ui_story_5072_50721602_82_dialog_content = "Bons sonhos a todos. Vejo vocês na próxima vez!",
  ui_story_5072_50721701_1_dialog_content = "Pare! Este é um navio particular. Ninguém entra sem autorização!",
  ui_story_5072_50721701_2_dialog_content = "Bem, um servo está guardando isso. Até a próxima então.",
  ui_story_5072_50721702_1_dialog_content = "Pare! Este é um navio particular. Ninguém entra sem autorização!",
  ui_story_5072_50721702_2_dialog_content = "Tenho um mandado dos Lins e da Guilda de Umbraton. Este lugar está abrigando um criminoso e devemos vasculhar a vizinhança!",
  ui_story_5072_50721702_3_dialog_content = "Mandado? Negócio oficial legítimo, entendi! Estou fora daqui!"
}
return config
